import { formatSpacedNumber, safeArray } from "../../../../common";
import { game2048Config } from "../../../../config.game2048";
import { DialogButtonActions } from "../../../../view-elements/ui/createCindDialog";
import { getLocalizedText } from "../../../../view-elements/locale";
import type { IGame2048EndStateData } from "./events";
import type { CindDialogData } from "./types";

const f = formatSpacedNumber;

interface IProps extends IGame2048EndStateData {
  rewardUndoAvailable: boolean;
}

/**
 *  Вернуть базовые данные для диалога
 **/
export function calcDialogState({
  playWinState,
  isMaxTileReached,
  canContinueAfterWin,
  undoAmount,
  rewardUndoAvailable,
  historyLength,
  winValue,
  maxTileValue,
}: IProps): CindDialogData {
  const hasUndoPossibility = game2048Config.undoFeature && historyLength > 0;
  const isUndoPossible = undoAmount > 0 && hasUndoPossibility;
  const isRewardUndoPossible = undoAmount === 0 && rewardUndoAvailable && hasUndoPossibility;

  const undoAction: DialogButtonActions | undefined = isUndoPossible
    ? DialogButtonActions.undo
    : isRewardUndoPossible
      ? DialogButtonActions.rewardUndo
      : undefined;

  switch (playWinState) {
    case "win": {
      /**
       * максимлаьная победа - максимальная плитка в 2048
       * крайне редкое событие
       * поэтому дополнительно делаем промежуточну победу
       *  **/
      if (isMaxTileReached) {
        return {
          type: "winMax",
          title: getLocalizedText("dialogWinMaxTitle"),
          message: getLocalizedText("dialogWinMaxMessage", {
            maxTileValue: f(maxTileValue),
          }),
          actions: [DialogButtonActions.newGame],
        };
      }

      if (!canContinueAfterWin) {
        /** достигли промежуточной победы но не можем продолжать **/
        return {
          type: "winNoMove",
          title: getLocalizedText("dialogWinTitle"),
          message: getLocalizedText("dialogWinNoMoveMessage", {
            winValue: f(winValue),
          }),
          actions: safeArray([undoAction, DialogButtonActions.newGame]),
        };
      }

      /** достигли промежуточной победы И можем продолжать **/
      return {
        type: "winHasMove",
        title: getLocalizedText("dialogWinTitle"),
        message: getLocalizedText("dialogWinHasMoveMessage", {
          winValue: f(winValue),
          maxTileValue: f(maxTileValue),
        }),
        actions: [DialogButtonActions.continue, DialogButtonActions.newGame],
      };
    }

    case "game-over": {
      /** нет ходов **/
      return {
        type: "failNoMove",
        title: getLocalizedText("dialogNoMovesTitle"),
        message: getLocalizedText("dialogNoMovesMessage"),
        actions: safeArray([undoAction, DialogButtonActions.newGame]),
      };
    }
  }
}
