import { AutoAssetImage, getAtlasImgAsset } from "../../autoAssetHelpers";
import { createImageButton } from "../../common/ui/2026-06-cind-block";
import { fitToSize } from "../../common";
import { vpx } from "../../common/vpx";
import { addButtonSounds } from "../../config.sound";

interface IProps {
  scene: Phaser.Scene;
  type: ButtonType;
  onClick: (obj: Phaser.GameObjects.GameObject) => void;
}

type ButtonType = "new" | "undo" | "hammer";
const assetsMap: Record<ButtonType, AutoAssetImage> = {
  new: "buttonCareta",
  undo: "buttonUndo",
  hammer: "buttonHammer",
};

/**
 *  Картиночная кнопка

 *  -- картинка
 *  -- onClick
 *  -- эффект hover без gl
 *  -- эффект нажатия?
 *  -   размеры в vpx
 *  -   enable/disable
 *
 *   излучает
 *   onClick: 'onButtonClick',
 *   onHover: 'onButtonHover',
 *   onOut: 'onButtonOut',
 **/
export function createCindIconButton({ scene, onClick, type }: IProps) {
  const image = createImageButton({
    scene,
    imageAsset: getAtlasImgAsset(assetsMap[type]),
    onClick,
    onEnabledChange: (obj, enabled) => {
      obj.setAlpha(enabled ? 1 : 0.45);
    },
  });
  fitToSize({
    gameObject: image,
    width: vpx(105),
    height: vpx(120),
  });

  image.name = `button-${type}`;
  // привязка локальных звуков
  addButtonSounds(image);
  return image;
}
