import { getFontFamilyAsset } from "../../autoAssetHelpers";
import { vpx } from "../../common";
import { makeView } from "../../common/gameObjects/makeView/makeView";

type DialogTextType = "title" | "info" | "footer";

interface IProps {
  scene: Phaser.Scene;
  text: string;
  type: DialogTextType;
  maxWidthPx?: number;
}

const styleMap: Record<DialogTextType, Phaser.Types.GameObjects.Text.TextStyle> = {
  title: {
    fontFamily: getFontFamilyAsset("interSemibold"),
    fontSize: `${vpx(50)}px`,
    fontStyle: "bold",
    align: "center",
    color: "#DD6E0B",
  },
  info: {
    fontFamily: getFontFamilyAsset("georgiaRegular"),
    fontSize: `${vpx(36)}px`,
    color: "#000000",
    align: "center",
  },
  footer: {
    fontFamily: getFontFamilyAsset("interSemibold"),
    fontSize: `${vpx(18)}px`,
    align: "center",
    color: "#6E6D6D",
  },
};

export function createDialogTexts({ scene, text, type, maxWidthPx = vpx(560) }: IProps) {
  const style: Phaser.Types.GameObjects.Text.TextStyle = {
    ...styleMap[type],
    wordWrap: { width: maxWidthPx },
  };
  return makeView(scene, (b) => b.text({ text, style }));
}
