import { FireworksEffect, TypedEventsEmitter } from "../../../../common";
import type { ICommonModalSceneHandle } from "../../../../common/game-core";
import { openCommonModalInScene } from "../../../../common/game-core";
import {
  createCindDialog,
  DialogButtonActions,
} from "../../../../view-elements/ui/createCindDialog";
import { calcDialogState } from "./calcDialogState";
import type { ICinderella2048GameOverDialogManagerEvents } from "./events";
import type { CindDialogData } from "./types";
import { adService } from "../../../../services";
import { cinderella2048FireworksConfig } from "../../../../config.fireworks";
import { autoAssetsConfig } from "../../../../autoAssetsConfig";

interface ICinderella2048GameOverDialogManagerProps {
  scene: Phaser.Scene;
  events: TypedEventsEmitter<ICinderella2048GameOverDialogManagerEvents>;
}

/** Управляет стандартным диалогом победы и конца игры через modal scene. */
export class CindDialogManager extends Phaser.GameObjects.Zone {
  private get gameEvents() {
    return this.props.events;
  }

  private dialog?: ICommonModalSceneHandle;

  /** Создает manager и подписывает его на runtime-состояние победного экрана. */
  constructor(private readonly props: ICinderella2048GameOverDialogManagerProps) {
    super(props.scene, 0, 0);
    this.gameEvents.on("game2048EndStateReady", (endStateData) => {
      const dialogData = calcDialogState({
        ...endStateData,
        rewardUndoAvailable: adService.isRewardAdEnabled,
      });

      /**
       *  Есть диалог - показываем его!
       **/
      if (dialogData) {
        this.openDialog(dialogData);
      }
    });

    props.scene.add.existing(this);
  }

  /** Закрывает активный диалог и снимает подписки. */
  destroy(fromScene?: boolean): void {
    this.closeDialog();
    super.destroy(fromScene);
  }

  /** Открывает диалог поверх игры и блокирует parent scene стандартным overlay. */
  private openDialog(dialogData: CindDialogData): void {
    const { scene } = this.props;

    this.closeDialog();
    this.dialog = openCommonModalInScene({
      parentScene: scene,
      createContent: (scene) => this.createDialogContent(scene, dialogData),
      props: {
        animationDuration: 180,
        overlayAlpha: 0.06,
        overlayColor: "#0d0b19",
        isCloseOnOverlayClick: false,
        onClose: () => {
          this.dialog = undefined;
        },
      },
    });
  }

  /** Создает графику и кнопки диалога в отдельной modal scene. */
  private createDialogContent(scene: Phaser.Scene, data: CindDialogData) {
    this.createDialogFireworks(scene, data);
    this.playWinFanfare(scene, data);
    const dialogView = createCindDialog({
      scene,
      ...data,
      onAction: (action) => this.onAction(action),
    });

    scene.add.existing(dialogView);

    return dialogView;
  }

  /** Один раз проигрывает фанфару только для победного диалога плитки 2048. */
  private playWinFanfare(scene: Phaser.Scene, data: CindDialogData): void {
    if (data.type !== "winHasMove" && data.type !== "winNoMove") {
      return;
    }

    scene.sound.play(autoAssetsConfig.sounds.fanfare.name, { loop: false });
  }

  /**
   * Диалог создает собственный эффект, потому что modal scene имеет отдельные display list и lifecycle.
   * Он не использует игровой `FireworksLayer` и уничтожается по shutdown именно своей modal scene.
   **/
  private createDialogFireworks(scene: Phaser.Scene, data: CindDialogData): void {
    if (data.type === "failNoMove") {
      return;
    }

    const { assets, dialog: effectConfig } = cinderella2048FireworksConfig;
    const fireworks = new FireworksEffect({
      scene,
      ...assets,
      ...effectConfig,
    });
    fireworks.start();
    scene.events.once(Phaser.Scenes.Events.SHUTDOWN, () => fireworks.destroy());
  }

  private onAction(action: DialogButtonActions) {
    this.closeDialog();

    switch (action) {
      case DialogButtonActions.newGame:
        this.gameEvents.emit("game2048NewGameClick");
        break;
      case DialogButtonActions.continue:
        this.gameEvents.emit("game2048ContinueClick");
        break;
      case DialogButtonActions.undo:
        this.gameEvents.emit("game2048UndoRequest");
        break;
      case DialogButtonActions.rewardUndo:
        this.gameEvents.emit('requestRewardAd', {
          rewardType: "undo",
        });
        break;
    }
  }

  private closeDialog(): void {
    this.dialog?.destroy();
    this.dialog = undefined;
  }
}
