import { makeAlign } from "@kvisaz/phaser-sugar";
import { column, safeArray, vpx } from "../../common";
import { makeView } from "../../common/gameObjects/makeView/makeView";
import { getAtlasImgAsset } from "../../autoAssetHelpers";
import { createDialogTexts } from "./createDialogTexts";
import { createCindTextButton, ICindTextButtonProps } from "./createCindTextButton";
import { getLocalizedText } from "../locale";

export enum DialogButtonActions {
  newGame = "newGame",
  undo = "undo",
  continue = "continue",
  rewardUndo = "rewardUndo",
}

export type DialogTexts = {
  title: string;
  message: string;
  actions: DialogButtonActions[];
  footer?: string;
};

interface ICinderella2048GameOverDialogViewProps extends DialogTexts {
  /** Modal scene, внутри которой рисуется карточка диалога. */
  scene: Phaser.Scene;
  onAction: (action: DialogButtonActions) => void;
}

export function createCindDialog({
  scene,
  title,
  message,
  footer,
  actions,
  onAction,
}: ICinderella2048GameOverDialogViewProps) {
  const bgNineAsset = getAtlasImgAsset("frame03Nine90");
  const bg = makeView(scene, (builder) =>
    builder.nine({
      ...bgNineAsset,
      width: vpx(715),
      height: vpx(550),
      padding: vpx(90),
    }),
  );

  const titleView = createDialogTexts({
    scene,
    text: title,
    type: "title",
  });

  const messageView = createDialogTexts({
    scene,
    text: message,
    type: "info",
  });

  const buttons = actions.map((action) => makeButton(scene, action, onAction));

  const footerView =
    footer != null
      ? createDialogTexts({
          scene,
          text: footer,
          type: "footer",
        })
      : undefined;

  makeAlign((align) => {
    align.anchor(bg).centerX(titleView).topIn(titleView, vpx(40));
    align.anchor(titleView).centerX(messageView).bottomTo(messageView, vpx(20));
    const buttonRow = column(buttons, { nextOffsetY: vpx(20) });
    align.anchor(bg).centerX(buttonRow).bottomIn(buttonRow, -vpx(80));
    if (footerView) {
      align.anchor(bg).centerX(footerView).bottomIn(footerView, -vpx(20));
    }
  });

  const children = safeArray([bg, titleView, messageView, ...buttons, footerView]);
  return makeView(scene, (builder) => builder.con(children));
}

function makeButton(
  scene: Phaser.Scene,
  action: DialogButtonActions,
  onAction: (action: DialogButtonActions) => void,
): Phaser.GameObjects.Container {
  const buttonProps: ICindTextButtonProps = {
    scene,
    text: "",
    onClick: () => onAction(action),
    rewardIcon: false,
    type: "primary",
  };
  switch (action) {
    case DialogButtonActions.newGame: {
      buttonProps.text = getLocalizedText("dialogActionNewGame");
      buttonProps.type = "primary";
      break;
    }
    case DialogButtonActions.continue: {
      buttonProps.text = getLocalizedText("dialogActionContinue");
      buttonProps.type = "secondary";
      break;
    }
    case DialogButtonActions.undo: {
      buttonProps.text = getLocalizedText("dialogActionUndo");
      buttonProps.type = "secondary";
      break;
    }
    case DialogButtonActions.rewardUndo: {
      buttonProps.text = getLocalizedText("dialogActionUndo");
      buttonProps.type = "secondary";
      buttonProps.rewardIcon = true;
      break;
    }
  }

  return createCindTextButton(buttonProps);
}
