import { ImageFrameData } from "../../game-core";
import { makeView } from "../../gameObjects/makeView/makeView";
import { makeButton } from "../../gameObjects";


export interface ImageButtonProps {
  scene: Phaser.Scene;
  imageAsset: ImageFrameData;
  onClick: (obj: Phaser.GameObjects.Image) => void;
  onEnabledChange?: (obj: Phaser.GameObjects.Image, enabled: boolean) => void;
}

export function createImageButton({
                                    scene,
                                    onClick,
                                    imageAsset,
                                    onEnabledChange,
                                  }: ImageButtonProps) {
  const image = makeView(scene, (b) => b.img(imageAsset));
  makeButton({
    obj: image,
    onClick,
    onEnabledChange
  })
  return image;
}
