import { AlignMethod, makeAlign } from "@kvisaz/phaser-sugar";
import {
  formatSpacedNumber,
  type Game2048Config,
  type IGame2048State,
  InputBlocker,
  Observable,
  row,
  TypedEventsEmitter,
} from "../../../../common";
import { vpx } from "../../../../common";
import { createCindUiInfo } from "../../../../view-elements/ui/createCindUiInfo";
import { createCindIconButton } from "../../../../view-elements/ui/createCindIconButton";
import { createCindConsumableButton } from "../../../../view-elements/ui/createCindConsumableButton";
import { adService } from "../../../../services";
import { getLocalizedText } from "../../../../view-elements/locale";
import type { ICinderella2048UiEvents } from "./events";

interface ICinderella2048UiProps {
  scene: Phaser.Scene;
  gameState: Observable<IGame2048State>;
  isHammerFeatureEnabled: boolean;
  isUndoFeatureEnabled: boolean;
  game2048Config: Game2048Config;
  events: TypedEventsEmitter<ICinderella2048UiEvents>;
}

/** Рисует верхнюю панель счета, рекорда, ходов и кнопок. */
export class Cinderella2048Ui extends Phaser.GameObjects.Container {
  private undoButton: Phaser.GameObjects.Container;
  private hammerButton: Phaser.GameObjects.Container;

  private get gameState(): Observable<IGame2048State> {
    return this.props.gameState;
  }

  private get gameEvents() {
    return this.props.events;
  }

  private scoreUI: Phaser.GameObjects.Container;
  private bestUI: Phaser.GameObjects.Container;
  private movesUI: Phaser.GameObjects.Container;

  private inputBlocker: InputBlocker | undefined;

  private unSubs: (() => void)[] = [];

  /** Создает HUD игрового компонента. */
  constructor(private props: ICinderella2048UiProps) {
    super(props.scene, 0, 0);
    const { scene, isHammerFeatureEnabled, isUndoFeatureEnabled } = this.props;
    const { score, moves, bestScore, hammerAmount, undoAmount } = this.gameState.getState();
    this.scoreUI = createCindUiInfo({
      scene,
      initValue: formatNumber(score),
      title: getLocalizedText("score"),
    });
    this.bestUI = createCindUiInfo({
      scene,
      initValue: formatNumber(bestScore),
      title: getLocalizedText("bestScore"),
    });
    this.movesUI = createCindUiInfo({
      scene,
      initValue: formatNumber(moves),
      title: getLocalizedText("moves"),
    });

    makeAlign((align) => {
      const gap = 32;
      const infoRow = row([this.scoreUI, this.bestUI, this.movesUI], { nextOffsetX: gap });
      align.anchorSceneScreen(scene).setPosition(infoRow, vpx(282), vpx(10));
    });

    const newButton = createCindIconButton({
      scene,
      type: "new",
      onClick: (obj) => {
        this.gameEvents.emit("game2048NewGameClick");
        obj.setData("enabled", false);
      },
    });

    const undoButton = createCindConsumableButton({
      scene,
      type: "undo",
      initValue: undoAmount,
      isRewardModeEnabled: () => this.getUndoRewardMode(),
      onClick: () => {
        if (this.getUndoRewardMode()) {
          this.requestUndoReward();
        } else {
          this.gameEvents.emit("game2048UndoRequest");
        }
      },
    });
    this.undoButton = undoButton;
    undoButton.setVisible(isUndoFeatureEnabled);

    const hammerButton = createCindConsumableButton({
      scene,
      type: "hammer",
      initValue: hammerAmount,
      isRewardModeEnabled: () => adService.isRewardAdEnabled,
      onClick: () => {
        if (this.getHammerRewardMode()) {
          this.requestHammerReward();
        } else {
          this.gameEvents.emit("game2048HammerButtonRequest");
        }
      },
    });
    this.hammerButton = hammerButton;
    hammerButton.setVisible(isHammerFeatureEnabled);

    const buttons = [newButton, undoButton, hammerButton];

    makeAlign((align) => {
      const buttonRow = row(buttons, { nextOffsetX: vpx(20), alignToAnchor: AlignMethod.TOP_IN });
      align.anchorSceneScreen(scene).leftIn(buttonRow, vpx(1162)).topIn(buttonRow, vpx(11));
    });

    this.add([this.bestUI, this.movesUI, this.scoreUI, newButton, undoButton, hammerButton]);
    props.scene.add.existing(this);
    this.unSubs.push(this.gameState.on((state) => this.updateValues(state)));
    this.updateValues(this.gameState.getState());
  }

  /** Проверяет, можно ли получить отмену за просмотр рекламы. */
  private getUndoRewardMode(gameState: IGame2048State = this.gameState.getState()) {
    return (
      gameState.undoAmount === 0 && gameState.history.length > 0 && adService.isRewardAdEnabled
    );
  }

  private getHammerRewardMode(gameState: IGame2048State = this.gameState.getState()) {
    return gameState.hammerAmount === 0 && adService.isRewardAdEnabled;
  }

  /** Запрашивает rewarded-рекламу для начисления отмены хода. */
  private requestUndoReward(): void {
    this.gameEvents.emit("requestRewardAd", {
      rewardType: "undo",
    });
  }

  /** Запрашивает rewarded-рекламу для начисления молотка. */
  private requestHammerReward(): void {
    this.gameEvents.emit("requestRewardAd", {
      rewardType: "hammer",
    });
  }

  /** Уничтожает UI и снимает подписки на состояние. */
  destroy(fromScene?: boolean): void {
    this.unSubs.forEach((u) => u());
    this.inputBlocker?.destroy(); // не обязательный компонент может и не создан быть
    super.destroy(fromScene);
  }

  /** Обновляет числовые значения и состояние кнопки отмены. */
  updateValues(gameState: IGame2048State): void {
    this.scoreUI.setData("value", formatNumber(gameState.score));
    this.bestUI.setData("value", formatNumber(gameState.bestScore));
    this.movesUI.setData("value", formatNumber(gameState.moves));
    this.undoButton.setData("value", gameState.undoAmount);

    const undoEnabled = this.getUndoRewardMode(gameState)
      ? true
      : gameState.undoAmount > 0 && gameState.history.length > 0;
    this.undoButton.setData("enabled", undoEnabled);

    this.hammerButton.setData("value", gameState.hammerAmount);
    const hammerEnabled = this.getHammerRewardMode(gameState)
      ? true
      : gameState.hammerAmount > 0 && this.isHammerTime(gameState);
    this.hammerButton.setData("enabled", hammerEnabled);

    this.blockInput(gameState.inputLocked);
  }

  private isHammerTime(gameState: IGame2048State) {
    return (
      gameState.filledTiles >= this.props.game2048Config.hammerBoardFillAmountMin
    );
  }

  /** Создает или снимает прозрачный перехватчик ввода поверх HUD без изменения состояния кнопок. */
  private blockInput(blocked: boolean) {
    this.inputBlocker?.destroy();
    this.inputBlocker = undefined;

    if (blocked) {
      const { scene } = this.props;
      const inputBlocker = new InputBlocker({ scene });
      makeAlign((align) => {
        align.anchorSceneScreen(scene).center(inputBlocker);
      });
      scene.add.existing(inputBlocker);
      this.inputBlocker = inputBlocker;
    }
  }
}

/** пусть он тонкий зато сосредотачивает логику в 1 месте тут **/
function formatNumber(num: number) {
  return formatSpacedNumber(num);
}
