import * as en from "./json/en.json";
import * as ru from "./json/ru.json";
import { getUrlParam, renderTemplateString } from "../../common";

export type Locale = "en" | "ru";

const srcTexts = {
  en,
  ru,
} as const;

/** для типизации **/
const texts: Record<Locale, (typeof srcTexts)[Locale]> = srcTexts;

export type LocaleKey = keyof typeof texts.en;

/** simple dimple localization **/
const DEFAULT_LOCALE: Locale = "ru";

let locale: Locale = DEFAULT_LOCALE;

function isLocale(str: unknown): str is Locale {
  return str === "en" || str === "ru";
}

function normalizeLocale(str: unknown): Locale | undefined {
  if (isLocale(str)) return str;
}

const setLocale = (newLocale: Locale) => (locale = newLocale);

export const getCurrentLocale = () => locale;

export const setLocaleFromString = (str: string | undefined) => {
  const normalized = normalizeLocale(str);
  if (normalized) setLocale(normalized);
};

export const getLocalizedText = (
  text: LocaleKey,
  data: Record<string, string | number> = {},
): string => {
  return renderTemplateString(texts[locale][text], data);
};

export const getLocaleFromUrl = () => {
  return normalizeLocale(getUrlParam("locale"));
};

export type ExternalLocaleGetter = () => string | undefined;

/**
 * меняет язык по первому ненулевому результату от геттера
 * рекомендуется ставить
 * - в начале сцен
 * - для массива геттеров - создавать config.locale.json
 * **/
export const setLocaleFromExternal = (getters: ExternalLocaleGetter[]) => {
  for (let i = 0; i < getters.length; i++) {
    const locale = getters[i]();
    if (isLocale(locale)) {
      setLocale(locale);
      return;
    }
  }
};
