import {
  createBasicGeneratedParticleEffectSet,
  randomRange,
  TypedEventsEmitter,
  vpx,
} from "../../../../common";
import { cinderella2048ParticleConfig } from "./constants";
import type {
  ICinderella2048EffectsLayerEvents,
  IGame2048EffectPayload,
} from "./events";
import type { ParticleColorSource, ParticleShape } from "./types";

type ParticleEmitter = Phaser.GameObjects.Particles.ParticleEmitter;
type ParticleEmitterConfig = Phaser.Types.GameObjects.Particles.ParticleEmitterConfig;

interface IBurstEmitter {
  emitter: ParticleEmitter;
  style: {
    tints: number[];
    tintIndex: number;
  };
}

interface IProps {
  scene: Phaser.Scene;
  events: TypedEventsEmitter<ICinderella2048EffectsLayerEvents>;
}

interface ICreateEmitterProps {
  speed: readonly [number, number];
  radius: readonly [number, number];
  lifeSeconds: readonly [number, number];
  angle?: readonly [number, number];
  velocityYOffset?: number;
}

interface IExplodeProps {
  burstEmitter: IBurstEmitter;
  shapes: readonly ParticleShape[];
  colors: readonly string[];
  count: number;
  x: number;
  y: number;
}

/** Слушает события сцены и создает игровые эффекты через Phaser ParticleEmitter. */
export class Cinderella2048EffectsLayer {
  private mergeEmitter: IBurstEmitter;
  private hammerEmitter: IBurstEmitter;
  private newTileEmitter: IBurstEmitter;
  private victoryEmitter: IBurstEmitter;

  private get gameEvents() {
    return this.props.events;
  }

  /** Создает слой Phaser emitters и подписывает его на события игровых эффектов. */
  constructor(private props: IProps) {
    createBasicGeneratedParticleEffectSet({
      scene: props.scene,
      textureName: cinderella2048ParticleConfig.texture.name,
      shapeSize: cinderella2048ParticleConfig.texture.sourceShapeSize,
    });

    this.mergeEmitter = this.createEmitter(cinderella2048ParticleConfig.merge);
    this.hammerEmitter = this.createEmitter(cinderella2048ParticleConfig.hammer);
    this.newTileEmitter = this.createEmitter(cinderella2048ParticleConfig.newTile);
    this.victoryEmitter = this.createEmitter(cinderella2048ParticleConfig.victory);
    this.gameEvents.on("game2048Hammer", (payload) => this.spawnHammer(payload));
    this.gameEvents.on("game2048MergeParticles", (payload) => this.spawnMerge(payload));
    this.gameEvents.on("game2048NewTileParticles", (payload) => this.spawnNewTile(payload));
    this.gameEvents.on("game2048VictoryParticles", (payload) =>
      this.spawnRoyalBurst(payload),
    );
    this.gameEvents.on("game2048ClearParticles", () => this.clearParticles());
  }

  /** Останавливает активные частицы и уничтожает постоянные emitters слоя. */
  destroy(): void {
    this.clearParticles();
    this.forEachEmitter((emitter) => emitter.destroy());
  }

  /** Создает вспышку при слиянии с прежним чередованием форм и цветов. */
  private spawnMerge(payload: IGame2048EffectPayload): void {
    this.explode({
      burstEmitter: this.mergeEmitter,
      shapes: cinderella2048ParticleConfig.merge.shapes,
      colors: this.resolvePayloadColors(cinderella2048ParticleConfig.merge.colorPattern, payload),
      count: cinderella2048ParticleConfig.merge.count,
      x: payload.x,
      y: payload.y,
    });
  }

  /** Создает резкий разлет крупных осколков после удара молотком. */
  private spawnHammer(payload: IGame2048EffectPayload): void {
    this.explode({
      burstEmitter: this.hammerEmitter,
      shapes: cinderella2048ParticleConfig.hammer.shapes,
      colors: cinderella2048ParticleConfig.hammer.colors,
      count: cinderella2048ParticleConfig.hammer.count,
      x: payload.x,
      y: payload.y,
    });
  }

  /** Создает короткую ромбовидную искру при появлении новой плитки. */
  private spawnNewTile(payload: IGame2048EffectPayload): void {
    this.explode({
      burstEmitter: this.newTileEmitter,
      shapes: cinderella2048ParticleConfig.newTile.shapes,
      colors: this.resolvePayloadColors(cinderella2048ParticleConfig.newTile.colorPattern, payload),
      count: cinderella2048ParticleConfig.newTile.count,
      x: payload.x,
      y: payload.y,
    });
  }

  /** Создает направленный вверх праздничный залп для победной стадии. */
  private spawnRoyalBurst(payload: IGame2048EffectPayload): void {
    this.explode({
      burstEmitter: this.victoryEmitter,
      shapes: cinderella2048ParticleConfig.victory.shapes,
      colors: this.resolvePayloadColors(cinderella2048ParticleConfig.victory.colorPattern, payload),
      count: cinderella2048ParticleConfig.victory.count,
      x: payload.x,
      y: payload.y,
    });
  }

  /** Создает выключенный emitter с физикой и затуханием исходных image-частиц. */
  private createEmitter(props: ICreateEmitterProps): IBurstEmitter {
    const style = {
      tints: [0xffffff],
      tintIndex: 0,
    };
    const emitterConfig: ParticleEmitterConfig = {
      frame: cinderella2048ParticleConfig.texture.frameNameByShape.circle,
      lifespan: {
        min: props.lifeSeconds[0] * 1000,
        max: props.lifeSeconds[1] * 1000,
      },
      speed: {
        min: vpx(props.speed[0]),
        max: vpx(props.speed[1]),
      },
      angle: {
        min: props.angle?.[0] ?? 0,
        max: props.angle?.[1] ?? 360,
      },
      accelerationY: {
        min: vpx(cinderella2048ParticleConfig.physics.gravity[0]),
        max: vpx(cinderella2048ParticleConfig.physics.gravity[1]),
      },
      scale: {
        min: (vpx(props.radius[0]) * 2) / cinderella2048ParticleConfig.texture.sourceShapeSize,
        max: (vpx(props.radius[1]) * 2) / cinderella2048ParticleConfig.texture.sourceShapeSize,
      },
      alpha: { start: 1, end: 0 },
      tint: () => {
        const tint = style.tints[style.tintIndex % style.tints.length];
        style.tintIndex += 1;
        return tint;
      },
      rotate: this.createRotationConfig(),
      emitting: false,
      emitCallback:
        props.velocityYOffset === undefined
          ? undefined
          : (particle: Phaser.GameObjects.Particles.Particle) => {
              particle.velocityY += vpx(props.velocityYOffset ?? 0);
            },
    };
    return {
      emitter: this.props.scene.add.particles(
        0,
        0,
        cinderella2048ParticleConfig.texture.name,
        emitterConfig,
      ),
      style,
    };
  }

  /** Запускает burst с прежним циклическим рисунком форм и цветов. */
  private explode(props: IExplodeProps): void {
    const { emitter, style } = props.burstEmitter;
    const frames = props.shapes.map((shape) => {
      return cinderella2048ParticleConfig.texture.frameNameByShape[shape];
    });

    style.tints = props.colors.map((color) => Phaser.Display.Color.HexStringToColor(color).color);
    style.tintIndex = 0;
    emitter.setEmitterFrame({ frames, cycle: true });
    emitter.explode(props.count, props.x, props.y);
  }

  /** Создает управляемое Phaser вращение с прежними случайными направлением и скоростью. */
  private createRotationConfig(): Phaser.Types.GameObjects.Particles.EmitterOpCustomUpdateConfig {
    return {
      onEmit: (particle) => {
        const startDegrees = randomRange(0, 360);

        if (particle) {
          const spinRadians = randomRange(
            cinderella2048ParticleConfig.physics.spinRadiansPerSecond[0],
            cinderella2048ParticleConfig.physics.spinRadiansPerSecond[1],
          );
          if (particle.data.rotate) {
            particle.data.rotate.min = startDegrees;
            particle.data.rotate.max =
              startDegrees + (Phaser.Math.RadToDeg(spinRadians) * particle.life) / 1000;
          }
        }

        return startDegrees;
      },
      onUpdate: (particle, _key, progress) =>
        Phaser.Math.Linear(particle.data.rotate!.min, particle.data.rotate!.max, progress),
    };
  }

  /** Преобразует семантический цветовой паттерн в цвета конкретной игровой стадии. */
  private resolvePayloadColors(
    pattern: readonly ParticleColorSource[],
    payload: IGame2048EffectPayload,
  ): string[] {
    const stage = cinderella2048ParticleConfig.stagesByValue[payload.value];

    return pattern.map((source) => {
      return source === "light" ? stage.colorLight : stage.particle;
    });
  }

  /** Мгновенно убирает все активные частицы из постоянных emitters слоя. */
  private clearParticles(): void {
    this.forEachEmitter((emitter) =>
      emitter.forEachAlive((particle) => particle.setPosition(), undefined).killAll(),
    );
  }

  /** Выполняет действие для каждого постоянного emitter слоя. */
  private forEachEmitter(callback: (emitter: ParticleEmitter) => void): void {
    for (const burstEmitter of [
      this.mergeEmitter,
      this.hammerEmitter,
      this.newTileEmitter,
      this.victoryEmitter,
    ]) {
      callback(burstEmitter.emitter);
    }
  }
}
