import { makeContainerInteractive } from "./makeContainerInteractive";
import { ButtonEvents } from "./addButtonViewInteractivity";
import { onGameObjectDataKeyChange } from "../onGameObjectDataKeyChange";

const makeButtonConfig = {
  hoverScale: 1.05,
  hoverRestoreDelayMs: 160,
  baseScaleDataKey: "button.makeButton.BaseScale",
  pointerInsideDataKey: "button.makeButton.PointerInside",
  restoreTimerDataKey: "button.makeButton.RestoreTimer",
} as const;

type ScalableGameObject = Phaser.GameObjects.GameObject & {
  scaleX: number;
  scaleY: number;
  setScale: (x: number, y?: number) => Phaser.GameObjects.GameObject;
};

export interface IMakeButtonProps<
  T extends Phaser.GameObjects.GameObject = Phaser.GameObjects.GameObject,
> {
  obj: T;
  onClick: (obj: T) => void;
  onHover?: (obj: T) => void;
  onOut?: (obj: T) => void;
  onEnabledChange?: (obj: T, enabled: boolean) => void;
}

interface IButtonScale {
  x: number;
  y: number;
}

/** Делает игровой объект кнопкой с коллбэками и hover-scale эффектом. */
export function makeButton<T extends Phaser.GameObjects.GameObject>({
  obj,
  onClick,
  onHover,
  onOut,
  onEnabledChange,
}: IMakeButtonProps<T>): T {
  const scene = obj.scene;
  if (scene == null) return obj;

  makeObjectInteractive(obj);

  addEnabling<T>(obj, onEnabledChange);

  const onPointerDown = () => {
    if (!getButtonEnabled(obj)) return;

    scene.events.emit(ButtonEvents.onClick, { gameObjectName: obj.name });
    handlePointerDown(obj, onClick);
  };

  const onPointerOver = () => {
    if (!getButtonEnabled(obj)) return;

    scene.events.emit(ButtonEvents.onHover, { gameObjectName: obj.name });
    handlePointerOver(obj, onHover);
  };

  const onPointerOut = () => {
    if (!getButtonEnabled(obj)) return;

    scene.events.emit(ButtonEvents.onOut, { gameObjectName: obj.name });
    handlePointerOut(obj, onOut);
  };

  const cleanupButtonTimer = () => {
    cancelHoverRestoreTimer(obj);
  };

  obj.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, onPointerDown);
  obj.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, onPointerOver);
  obj.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OUT, onPointerOut);

  obj.once(Phaser.GameObjects.Events.DESTROY, cleanupButtonTimer);

  return obj;
}

/** Включает input для объекта, используя точный container-hitArea только для контейнеров. */
function makeObjectInteractive(obj: Phaser.GameObjects.GameObject) {
  if (obj instanceof Phaser.GameObjects.Container) {
    makeContainerInteractive(obj);
    return;
  }

  obj.setInteractive({ useHandCursor: true });
}

/** Проверяет, включена ли кнопка по data.enabled. */
function getButtonEnabled(obj: Phaser.GameObjects.GameObject): boolean {
  return obj.getData("enabled") !== false;
}

/** Применяет enabled-состояние кнопки без навязывания визуального disabled-стиля. */
function applyButtonEnabledState<T extends Phaser.GameObjects.GameObject>(
  obj: T,
  enabled: boolean,
  onEnabledChange?: (obj: T, enabled: boolean) => void,
) {
  if (enabled) {
    if (obj.input == null) {
      makeObjectInteractive(obj);
    } else {
      obj.input.enabled = true;
    }
  } else {
    cancelHoverRestoreTimer(obj);
    restoreButtonBaseScale(obj);
    obj.setData(makeButtonConfig.pointerInsideDataKey, false);

    if (obj.input != null) {
      obj.input.enabled = false;
    }
  }

  onEnabledChange?.(obj, enabled);
}

/** Обрабатывает нажатие кнопки и временно сбрасывает hover-scale. */
function handlePointerDown<T extends Phaser.GameObjects.GameObject>(
  button: T,
  onClick: (obj: T) => void,
) {
  const scene = button.scene;
  if (scene == null) return;

  ensureButtonBaseScale(button);
  button.setData(makeButtonConfig.pointerInsideDataKey, true);

  cancelHoverRestoreTimer(button);
  restoreButtonBaseScale(button);
  scheduleHoverRestore(scene, button);
  onClick(button);
}

/** Обрабатывает вход указателя в кнопку и включает hover-scale. */
function handlePointerOver<T extends Phaser.GameObjects.GameObject>(
  button: T,
  onHover?: (obj: T) => void,
) {
  if (button.scene == null) return;

  onHover?.(button);
  ensureButtonBaseScale(button);
  button.setData(makeButtonConfig.pointerInsideDataKey, true);

  cancelHoverRestoreTimer(button);
  applyButtonHoverScale(button);
}

/** Обрабатывает выход указателя из кнопки и возвращает базовый scale. */
function handlePointerOut<T extends Phaser.GameObjects.GameObject>(
  button: T,
  onOut?: (obj: T) => void,
) {
  if (button.scene == null) return;

  onOut?.(button);
  ensureButtonBaseScale(button);
  button.setData(makeButtonConfig.pointerInsideDataKey, false);

  cancelHoverRestoreTimer(button);
  restoreButtonBaseScale(button);
}

/** Возвращает сохраненный базовый scale или запоминает текущий. */
function ensureButtonBaseScale(button: Phaser.GameObjects.GameObject): IButtonScale {
  const baseScale = button.getData(makeButtonConfig.baseScaleDataKey) as IButtonScale | undefined;
  if (baseScale != null) return baseScale;
  if (!isScalableGameObject(button)) return { x: 1, y: 1 };

  const nextBaseScale: IButtonScale = {
    x: button.scaleX,
    y: button.scaleY,
  };

  button.setData(makeButtonConfig.baseScaleDataKey, nextBaseScale);
  return nextBaseScale;
}

/** Планирует восстановление hover-scale после click-сброса, если указатель остался внутри. */
function scheduleHoverRestore(scene: Phaser.Scene, button: Phaser.GameObjects.GameObject) {
  const restoreTimer = scene.time.delayedCall(makeButtonConfig.hoverRestoreDelayMs, () => {
    button.setData(makeButtonConfig.restoreTimerDataKey, undefined);

    if (button.scene == null) return;
    if (button.getData(makeButtonConfig.pointerInsideDataKey) !== true) return;

    applyButtonHoverScale(button);
  });

  button.setData(makeButtonConfig.restoreTimerDataKey, restoreTimer);
}

/** Отменяет отложенное восстановление hover-scale. */
function cancelHoverRestoreTimer(button: Phaser.GameObjects.GameObject) {
  const restoreTimer = button.getData(makeButtonConfig.restoreTimerDataKey) as
    | Phaser.Time.TimerEvent
    | undefined;
  if (restoreTimer == null) return;

  restoreTimer.remove(false);
  button.setData(makeButtonConfig.restoreTimerDataKey, undefined);
}

/** Применяет hover-scale относительно сохраненного базового scale. */
function applyButtonHoverScale(button: Phaser.GameObjects.GameObject) {
  if (!isScalableGameObject(button)) return;

  const baseScale = ensureButtonBaseScale(button);
  const nextScaleX = baseScale.x * makeButtonConfig.hoverScale;
  const nextScaleY = baseScale.y * makeButtonConfig.hoverScale;

  button.setScale(nextScaleX, nextScaleY);
}

/** Возвращает button к сохраненному базовому scale. */
function restoreButtonBaseScale(button: Phaser.GameObjects.GameObject) {
  if (!isScalableGameObject(button)) return;

  const baseScale = ensureButtonBaseScale(button);
  button.setScale(baseScale.x, baseScale.y);
}

/** Проверяет, что объект поддерживает scale-эффект кнопки. */
function isScalableGameObject(obj: Phaser.GameObjects.GameObject): obj is ScalableGameObject {
  const maybeScalable = obj as Partial<ScalableGameObject>;

  return (
    typeof maybeScalable.scaleX === "number" &&
    typeof maybeScalable.scaleY === "number" &&
    typeof maybeScalable.setScale === "function"
  );
}

function addEnabling<T extends Phaser.GameObjects.GameObject>(
  obj: T,
  onEnabledChange?: (obj: T, enabled: boolean) => void,
) {
  const enabledData = obj.getData("enabled");
  if (enabledData == null) {
    obj.setData("enabled", true);
  }
  applyButtonEnabledState(obj, obj.getData("enabled"), onEnabledChange);

  onGameObjectDataKeyChange<boolean>({
    obj,
    dataKey: "enabled",
    callback: (enabled) => {
      applyButtonEnabledState(obj, enabled, onEnabledChange);
    },
  });
}
