import { AutoAssetImage, getAtlasImgAsset } from "../../../autoAssetHelpers";
import { TypedEventsEmitter } from "../../../common";
import { GameCursorType } from "../../../types";
import type { ICursorManagerEvents, ISetCursorEvent } from "./events";

interface ICursorManagerProps {
  scene: Phaser.Scene;
  defaultType: GameCursorType;
  events: TypedEventsEmitter<ICursorManagerEvents>;
}

type ImageCursorType = "wand" | "hammer";

const AssetMap: Record<ImageCursorType, AutoAssetImage> = {
  wand: "cursorWand64",
  hammer: "cursorHammer64",
};

const cursorManagerConfig = {
  defaultCursor: "auto",
  fallbackCursor: "auto",
  cursors: {
    wand: {
      assetName: AssetMap.wand,
      hotSpotX: 2,
      hotSpotY: 2,
    },
    hammer: {
      assetName: AssetMap.hammer,
      hotSpotX: 8,
      hotSpotY: 8,
    },
  },
} as const;

/**
 * Управляет CSS-курсором игрового canvas через события сцены.
 *
 * Важно: отдельные интерактивные объекты с `input.cursor = "pointer"` могут
 * временно переопределять этот курсор на hover, потому что Phaser задает cursor
 * также на уровне конкретного интерактивного объекта.
 */
export class CursorManager {
  private get sceneEvents() {
    return this.props.events;
  }

  /** Создает менеджер курсора и сразу применяет начальный тип. */
  constructor(private readonly props: ICursorManagerProps) {
    const { defaultType } = props;

    this.sceneEvents.on("setCursor", this.handleSetCursor);
    this.setCursor(defaultType);
  }

  /** Отписывает менеджер от событий и возвращает стандартный курсор. */
  public destroy(): void {
    const { scene } = this.props;

    scene.input.setDefaultCursor(cursorManagerConfig.defaultCursor);
  }

  /** Обрабатывает событие смены курсора. */
  private readonly handleSetCursor = (data: ISetCursorEvent): void => {
    this.setCursor(data.type);
  };

  /** Применяет нужный CSS-курсор к input manager сцены. */
  private setCursor(type: GameCursorType): void {
    const { scene } = this.props;

    if (type === "default") {
      scene.input.setDefaultCursor(cursorManagerConfig.defaultCursor);
      return;
    }

    scene.input.setDefaultCursor(this.createCursorCss(type));
  }

  /** Собирает CSS cursor value из URL автоассета и hot spot. */
  private createCursorCss(type: ImageCursorType): string {
    const cursorConfig = cursorManagerConfig.cursors[type];
    const asset = getAtlasImgAsset(cursorConfig.assetName);

    return `url("${asset.textureName}") ${cursorConfig.hotSpotX} ${cursorConfig.hotSpotY}, ${cursorManagerConfig.fallbackCursor}`;
  }
}
