const baseWidth = 1920;

let vpxK = 1;

/** Обновляет коэффициент дизайн-пикселей. Игра рассчитана на 16:9, не-16:9 отдельно не поддерживаем. */
export const setVpx = (width: number): void => {
  vpxK = width / baseWidth;
};

/** Переводит значение из дизайн-пикселей макета 1920x1080 в текущий размер игры. */
export const vpx = (value: number): number => {
  return Math.round(value * vpxK);
};
