export class MinimalTimeIntervalStrategy {
  private previousSaveTime: number = 0;

  constructor(private minIntervalMs: number) {}

  markTime() {
    this.previousSaveTime = Date.now();
  }

  getTimeToNextSave(): number {
    return Math.max(0, this.previousSaveTime + this.minIntervalMs - Date.now());
  }

  isAllowed() {
    return this.getTimeToNextSave() <= 0;
  }
}
