import { makeAlign } from "@kvisaz/phaser-sugar";
import { center, grid } from "../../../layout";
import { vpx } from "../../../vpx";
import { game2048CoreConfig } from "../model";
import type {
  Game2048GridModel,
  Game2048TileModel,
  IGame2048MoveResult,
} from "../model";
import type { IGame2048SpriteConfig } from "../types";
import { Game2048TileView } from "./Game2048TileView";
import type { IGame2048BoardViewConfig, IGame2048TileHit } from "./types";

interface IGame2048BoardViewProps {
  scene: Phaser.Scene;
  spriteConfig: IGame2048SpriteConfig;
  boardConfig: IGame2048BoardViewConfig;
}

interface IPlayGame2048MoveProps {
  grid: Game2048GridModel;
  result: IGame2048MoveResult;
  newTile?: Game2048TileModel;
  onSlideComplete: () => void;
  onComplete: () => void;
}

interface IFindGame2048TileHitAtPointProps {
  grid: Game2048GridModel;
  x: number;
  y: number;
}

/** Отвечает за статическую доску и action-driven представление плиток. */
export class Game2048BoardView extends Phaser.GameObjects.Container {
  private boardBackground: Phaser.GameObjects.NineSlice;
  private freeTileViews: Phaser.GameObjects.Image[][];
  private tilesLayer: Phaser.GameObjects.Container;
  private tileViews = new Map<number, Game2048TileView>();
  private hammerTileId?: number;

  /** Создает доску 2048 и слой плиток. */
  constructor(private props: IGame2048BoardViewProps) {
    super(props.scene, 0, 0);

    this.boardBackground = this.createBoardBackground();
    this.freeTileViews = this.createFreeTileViews();
    this.tilesLayer = props.scene.add.container(0, 0);
    this.add([this.boardBackground, ...this.freeTileViews.flat(), this.tilesLayer]);
    props.scene.add.existing(this);
    this.setupStaticBoardView();
    this.alignToSceneScreen();
  }

  /** Уничтожает доску и все связанные tweens плиток. */
  destroy(fromScene?: boolean): void {
    this.hammerTileId = undefined;
    this.tileViews.forEach((tileView) => tileView.destroy());
    this.tileViews.clear();
    super.destroy(fromScene);
  }

  /** Возвращает актуальные bounds указанной клетки в локальных координатах доски. */
  getCellBounds(row: number, col: number): Phaser.Geom.Rectangle {
    const bounds = this.freeTileViews[row][col].getBounds();

    return new Phaser.Geom.Rectangle(bounds.x - this.x, bounds.y - this.y, bounds.width, bounds.height);
  }

  /** Возвращает центр указанной клетки в мировых координатах. */
  getCellCenter(row: number, col: number): { x: number; y: number } {
    const bounds = this.freeTileViews[row][col].getBounds();

    return { x: bounds.centerX, y: bounds.centerY };
  }

  /** Возвращает центр всей доски. */
  getBoardCenter(): { x: number; y: number } {
    const bounds = this.boardBackground.getBounds();

    return { x: bounds.centerX, y: bounds.centerY };
  }

  /** Проверяет, попадает ли точка в границы доски. */
  containsPoint(x: number, y: number): boolean {
    return this.boardBackground.getBounds().contains(x, y);
  }

  /** Синхронно отображает модель без анимации или с появлением всех плиток. */
  render(gridModel: Game2048GridModel, animateSpawn = false): void {
    this.hammerTileId = undefined;
    this.tileViews.forEach((tileView) => tileView.destroy());
    this.tileViews.clear();

    gridModel.forEachTile((tile) => {
      const tileView = this.createTileView(tile);
      if (animateSpawn) {
        tileView.playSpawn();
      }
    });
  }

  /** Проигрывает slide, синхронизирует итоговую доску и запускает spawn/merge tails. */
  playMove(props: IPlayGame2048MoveProps): void {
    this.hammerTileId = undefined;
    this.stopAnimations();

    const destinations = new Map<Game2048TileView, { x: number; y: number }>();

    for (const motion of props.result.tileMotions) {
      const tileView = this.tileViews.get(motion.tileId);
      if (!tileView) {
        continue;
      }

      const bounds = this.getCellBounds(motion.toRow, motion.toCol);
      destinations.set(tileView, { x: bounds.centerX, y: bounds.centerY });
    }

    const movingTiles = [...destinations.keys()];
    const finishSlide = () => this.finishMoveAfterSlide(props);

    if (movingTiles.length === 0) {
      finishSlide();
      return;
    }

    this.scene.tweens.add({
      targets: movingTiles,
      x: (target: Game2048TileView) => destinations.get(target)?.x ?? target.x,
      y: (target: Game2048TileView) => destinations.get(target)?.y ?? target.y,
      duration: game2048CoreConfig.timings.moveMs,
      ease: Phaser.Math.Easing.Cubic.Out,
      onComplete: finishSlide,
    });
  }

  /** Находит видимую плитку под точкой курсора в мировых координатах. */
  findTileHitAtPoint(props: IFindGame2048TileHitAtPointProps): IGame2048TileHit | null {
    let hit: IGame2048TileHit | null = null;

    props.grid.forEachTile((tile) => {
      if (hit) {
        return;
      }

      const bounds = this.freeTileViews[tile.row][tile.col].getBounds();
      if (bounds.contains(props.x, props.y)) {
        hit = { id: tile.id, row: tile.row, col: tile.col };
      }
    });

    return hit;
  }

  /** Переключает дрожание только у текущей плитки под молотком. */
  setHammerTile(tileId?: number): void {
    if (this.hammerTileId === tileId) {
      return;
    }

    if (this.hammerTileId !== undefined) {
      this.tileViews.get(this.hammerTileId)?.setHammerShake(false);
    }

    this.hammerTileId = tileId;
    if (tileId !== undefined) {
      this.tileViews.get(tileId)?.setHammerShake(true);
    }
  }

  /** Создает фон доски на базе atlas-frame с nine-slice отступами. */
  private createBoardBackground(): Phaser.GameObjects.NineSlice {
    const { scene } = this.props;
    const { background } = this.props.boardConfig.assets;
    const { boardOpacity } = this.props.boardConfig.layout;
    const backgroundView = scene.add.nineslice(
      0,
      0,
      background.textureName,
      background.frameName,
      1,
      1,
      background.nineSlicePadding,
      background.nineSlicePadding,
      background.nineSlicePadding,
      background.nineSlicePadding,
    );

    backgroundView.setOrigin(0, 0);
    backgroundView.setAlpha(boardOpacity);

    return backgroundView;
  }

  /** Создает изображения свободных клеток в порядке обхода сетки. */
  private createFreeTileViews(): Phaser.GameObjects.Image[][] {
    const { scene } = this.props;
    const { freeTile } = this.props.boardConfig.assets;
    const { freeTileOpacity, tileHeight, tileWidth } = this.props.boardConfig.layout;
    const freeTileViews: Phaser.GameObjects.Image[][] = [];

    for (let row = 0; row < game2048CoreConfig.gridSize; row += 1) {
      const freeTileRow: Phaser.GameObjects.Image[] = [];

      for (let col = 0; col < game2048CoreConfig.gridSize; col += 1) {
        const freeTileView = scene.add.image(0, 0, freeTile.textureName, freeTile.frameName);

        freeTileView.setOrigin(0.5);
        freeTileView.setDisplaySize(vpx(tileWidth), vpx(tileHeight));
        freeTileView.setAlpha(freeTileOpacity);
        freeTileRow.push(freeTileView);
      }

      freeTileViews.push(freeTileRow);
    }

    return freeTileViews;
  }

  /** Один раз выставляет сетку свободных клеток и центрирует фон вокруг нее. */
  private setupStaticBoardView(): void {
    const { boardPadding, tileGap } = this.props.boardConfig.layout;
    const boardPaddingVpx = vpx(boardPadding);
    const tileGapVpx = vpx(tileGap);
    const firstTileBounds = this.freeTileViews[0][0].getBounds();
    const freeTileGrid = grid(this.freeTileViews, {
      cellWidth: firstTileBounds.width + tileGapVpx,
      cellHeight: firstTileBounds.height + tileGapVpx,
    });
    const gridBounds = freeTileGrid.getBounds();

    this.boardBackground.setSize(
      gridBounds.width + boardPaddingVpx * 2,
      gridBounds.height + boardPaddingVpx * 2,
    );
    center(this.boardBackground, freeTileGrid);
  }

  /** Центрирует доску по горизонтали и задает отступ от верхней границы экрана. */
  private alignToSceneScreen(): void {
    const { scene } = this.props;
    const { boardTop } = this.props.boardConfig.layout;

    makeAlign((align) => align.anchorSceneScreen(scene).centerX(this).topIn(this, vpx(boardTop)));
  }

  /** Создает и регистрирует view одной плитки в локальной клетке доски. */
  private createTileView(tile: Game2048TileModel): Game2048TileView {
    const tileView = new Game2048TileView({
      scene: this.scene,
      value: tile.value,
      bounds: this.getCellBounds(tile.row, tile.col),
      spriteConfig: this.props.spriteConfig,
    });

    this.tilesLayer.add(tileView);
    this.tileViews.set(tile.id, tileView);

    return tileView;
  }

  /** Завершает slide, применяет итоговую модель и ожидает все параллельные tails. */
  private finishMoveAfterSlide(props: IPlayGame2048MoveProps): void {
    const newTileView = this.reconcileGrid(props.grid, props.newTile?.id);
    const mergeTargetViews = props.result.mergeTargetIds
      .map((targetTileId) => this.tileViews.get(targetTileId))
      .filter((tileView): tileView is Game2048TileView => tileView !== undefined);
    let remainingAnimations = mergeTargetViews.length + (newTileView ? 1 : 0);
    const completeTail = () => {
      remainingAnimations -= 1;
      if (remainingAnimations === 0) {
        props.onComplete();
      }
    };

    /** Ошибка визуального эффекта не должна оставлять input заблокированным. */
    try {
      props.onSlideComplete();
    } finally {
      if (remainingAnimations === 0) {
        props.onComplete();
      } else {
        newTileView?.playSpawn(completeTail);
        mergeTargetViews.forEach((tileView) => tileView.playMerge(completeTail));
      }
    }
  }

  /** Сводит существующие view с итоговой моделью и возвращает новую плитку хода. */
  private reconcileGrid(
    gridModel: Game2048GridModel,
    newTileId?: number,
  ): Game2048TileView | undefined {
    const activeIds = new Set<number>();
    let newTileView: Game2048TileView | undefined;

    gridModel.forEachTile((tile) => {
      activeIds.add(tile.id);
      let tileView = this.tileViews.get(tile.id);

      if (tileView) {
        tileView.setTile(tile.value, this.getCellBounds(tile.row, tile.col));
      } else {
        tileView = this.createTileView(tile);
      }

      if (tile.id === newTileId) {
        newTileView = tileView;
      }
    });

    this.tileViews.forEach((tileView, tileId) => {
      if (!activeIds.has(tileId)) {
        tileView.destroy();
        this.tileViews.delete(tileId);
      }
    });
    this.clearMissingHammerTile();

    return newTileView;
  }

  /** Останавливает все tweens, принадлежащие текущим tile views. */
  private stopAnimations(): void {
    this.tileViews.forEach((tileView) => tileView.stopAnimations());
  }

  /** Сбрасывает hover молотка, если выбранная плитка уже удалена из view. */
  private clearMissingHammerTile(): void {
    if (this.hammerTileId !== undefined && !this.tileViews.has(this.hammerTileId)) {
      this.hammerTileId = undefined;
    }
  }
}
