import { AutoAssetImage, getAtlasImgAsset, getFontFamilyAsset } from "../../autoAssetHelpers";
import { fitToSize, makeButton, onDestroy, onGameObjectDataKeyChange, vpx } from "../../common";
import { makeView } from "../../common/gameObjects/makeView/makeView";
import { makeAlign } from "@kvisaz/phaser-sugar";
import { addButtonSounds } from "../../config.sound";

interface IProps {
  scene: Phaser.Scene;
  type: ButtonType;
  onClick: (obj: Phaser.GameObjects.GameObject) => void;
  initValue: number;
  isRewardModeEnabled?: () => boolean;
}

type ButtonType = "new" | "undo" | "hammer";
const assetsMap: Record<ButtonType, AutoAssetImage> = {
  new: "buttonCareta",
  undo: "buttonUndo",
  hammer: "buttonHammer",
};

/**
 *  Картиночная кнопка

 *  -- картинка
 *  -- onClick
 *  -- эффект hover без gl
 *  -- эффект нажатия?
 *  -   размеры в vpx
 *  -   enable/disable
 *
 *
 *     // менеджмент enabled/disabled -  только снаружи
 *     // если надо отключать при 0 - пусть думает Ui
 *     // иначе возникает непредсказуемое поведенеи
 *
 *   излучает
 *   onClick: 'onButtonClick',
 *   onHover: 'onButtonHover',
 *   onOut: 'onButtonOut',
 **/
export function createCindConsumableButton({
  scene,
  onClick,
  type,
  initValue,
  isRewardModeEnabled,
}: IProps) {
  const icon = makeView(scene, (b) => b.img(getAtlasImgAsset(assetsMap[type])));
  const textBgAsset = getAtlasImgAsset("frameSmallNine25");
  const textBg = makeView(scene, (b) => b.img(textBgAsset));
  const rewardIcon = makeView(scene, (b) => b.img(getAtlasImgAsset("iconPlayFull44")));

  const valueText = scene.add.text(0, 0, `${initValue}`, {
    fontFamily: getFontFamilyAsset("interSemibold"),
    fontSize: "24px",
    fontStyle: "bold",
    color: "#A2525B",
  });

  fitToSize({
    gameObject: icon,
    width: vpx(105),
    height: vpx(120),
  });
  fitToSize({
    gameObject: textBg,
    width: vpx(60),
    height: vpx(50),
  });
  fitToSize({
    gameObject: rewardIcon,
    width: vpx(32),
    height: vpx(32),
  });

  const layout = () =>
    makeAlign((align) => {
      align.anchor(icon).centerX(textBg).topIn(textBg, vpx(102));
      align.anchor(textBg).center(valueText, 0, vpx(4));
      align.anchor(textBg).center(rewardIcon, 0, vpx(4));
    });
  layout();

  const con = makeView(scene, (b) => {
    return b.con([textBg, valueText, icon, rewardIcon]);
  });

  con.name = `button-${type}`;
  con.setData("value", initValue);

  makeButton({
    obj: con,
    onClick,
    onEnabledChange: (obj, enabled) => {
      obj.setAlpha(enabled ? 1 : 0.45);
    },
  });
  // привязка локальных звуков
  addButtonSounds(con);

  /** Обновляет текст счетчика при изменении `data.value` на контейнере кнопки. */
  const updateValue = (value: number) => {
    const normalizedValue = Math.max(0, value);
    const isRewardMode = isRewardModeEnabled?.() === true && normalizedValue === 0;

    rewardIcon.setVisible(isRewardMode);
    valueText.setVisible(!isRewardMode);

    valueText.setText(`${normalizedValue}`);

    layout();
  };

  updateValue(initValue);

  const unSubValue = onGameObjectDataKeyChange<number>({
    obj: con,
    dataKey: "value",
    callback: updateValue,
  });

  onDestroy(con, unSubValue);

  return con;
}
