import {
  Game2048GridModel,
  Game2048Config,
  IGame2048MergeEvent,
  IGameCore2048Config,
  IHistorySnapshot,
  ISaveData,
} from "./model";
import type {
  Game2048PlayWinState,
  Game2048ToolMode,
  IGame2048State,
} from "./types";

interface ICreateInitStateProps {
  grid: Game2048GridModel;
  saveData: ISaveData;
  undoHistoryDepth: number;
  game2048Config: Game2048Config;
}

/** Создает полный стартовый state без дополнительного constructor update. */
export const createInitState = ({
  grid,
  saveData,
  undoHistoryDepth,
  game2048Config,
}: ICreateInitStateProps): IGame2048State => {
  const isNewGame = saveData.boardSnapshot == null;
  const hammerAmount = clampHammerAmount({
    hammerMax: game2048Config.hammerMax,
    amount: initConsumable({
      savedAmount: saveData.hammerAmount,
      startConfigAmount: game2048Config?.hammerStartAmount,
      isNewGame,
    }),
  });
  const undoAmount = clampUndoAmount({
    undoMax: game2048Config.undoMax,
    amount: initConsumable({
      savedAmount: saveData.undoAmount,
      startConfigAmount: game2048Config?.undoStartAmount,
      isNewGame,
    }),
  });
  const hasAvailableMoves = grid.canMove();
  const isMaxTileReached = isGridMaxTileReached(grid, game2048Config);
  const playWinState = calcPlayWinState({ grid, game2048Config });
  const won = calcNextGridWon({ grid, playWinState });
  const inputLocked = false;
  const history = restoreInitialHistory({
    history: saveData.history,
    undoHistoryDepth,
  });

  return {
    score: grid.score,
    bestScore: saveData.bestScore,
    moves: grid.moves,
    filledTiles: grid.getNotNullTiles(),
    undoAmount,
    hammerAmount,
    canContinueAfterWin: canContinueAfterWin({
      playWinState,
      hasAvailableMoves,
      isMaxTileReached,
      game2048Config,
    }),
    hasAvailableMoves,
    isMaxTileReached,
    playWinState,
    inputLocked,
    toolMode: "wand",
    boardSnapshot: createBoardSnapshot({ grid, won }),
    history,
    maxReachedTile: Math.max(saveData.maxReachedTile ?? 0, grid.getMaxValue()),
  };
};

interface ICreateMoveStateProps {
  prevState: IGame2048State;
  grid: Game2048GridModel;
  snapshotBeforeAction: IHistorySnapshot;
  undoHistoryDepth: number;
  mergeEvents: IGame2048MergeEvent[];
  game2048Config: Game2048Config;
}

/** Создает state после успешного хода по уже измененной доске. */
export const createMoveState = ({
  prevState,
  grid,
  snapshotBeforeAction,
  undoHistoryDepth,
  mergeEvents,
  game2048Config,
}: ICreateMoveStateProps): IGame2048State => {
  const hasAvailableMoves = grid.canMove();
  const isMaxTileReached = isGridMaxTileReached(grid, game2048Config);
  const playWinState = calcPlayWinState({ grid, game2048Config });
  const history = createNextHistory({
    prevHistory: prevState.history,
    snapshotBeforeAction,
    undoHistoryDepth,
  });
  const hammerAmount = calcHammerAmountAfterMergeRewards({
    prevHammerAmount: prevState.hammerAmount,
    mergeEvents,
    gameConfig: game2048Config,
  });
  const won = calcNextGridWon({ grid, playWinState });
  const inputLocked = true;

  return {
    ...prevState,
    score: grid.score,
    bestScore: Math.max(prevState.bestScore, grid.score),
    moves: grid.moves,
    hammerAmount,
    filledTiles: grid.getNotNullTiles(),
    canContinueAfterWin: canContinueAfterWin({
      playWinState,
      hasAvailableMoves,
      isMaxTileReached,
      game2048Config,
    }),
    hasAvailableMoves,
    isMaxTileReached,
    playWinState,
    inputLocked,
    toolMode: "wand",
    boardSnapshot: createBoardSnapshot({
      grid,
      won,
    }),
    history,
    maxReachedTile: Math.max(prevState.maxReachedTile, grid.getMaxValue()),
  };
};

interface ICreateHammerStateProps {
  prevState: IGame2048State;
  grid: Game2048GridModel;
  snapshotBeforeAction: IHistorySnapshot;
  undoHistoryDepth: number;
  game2048Config: Game2048Config;
}

/** Создает state после применения молотка по уже измененной доске. */
export const createHammerState = ({
  prevState,
  grid,
  snapshotBeforeAction,
  undoHistoryDepth,
  game2048Config,
}: ICreateHammerStateProps): IGame2048State => {
  const hasAvailableMoves = grid.canMove();
  const isMaxTileReached = isGridMaxTileReached(grid, game2048Config);
  const playWinState = calcPlayWinState({ grid, game2048Config });
  const history = createNextHistory({
    prevHistory: prevState.history,
    snapshotBeforeAction,
    undoHistoryDepth,
  });
  const hammerAmount = clampHammerAmount({
    hammerMax: game2048Config.hammerMax,
    amount: prevState.hammerAmount - 1,
  });
  const won = calcNextGridWon({ grid, playWinState });
  const inputLocked = false;

  return {
    ...prevState,
    score: grid.score,
    moves: grid.moves,
    toolMode: "wand",
    hammerAmount,
    filledTiles: grid.getNotNullTiles(),
    canContinueAfterWin: canContinueAfterWin({
      playWinState,
      hasAvailableMoves,
      isMaxTileReached,
      game2048Config,
    }),
    hasAvailableMoves,
    isMaxTileReached,
    playWinState,
    inputLocked,
    history,
    boardSnapshot: createBoardSnapshot({
      grid,
      won,
    }),
  };
};

interface ICreateUndoStateProps {
  prevState: IGame2048State;
  grid: Game2048GridModel;
  game2048Config: Game2048Config;
}

/** Создает state после undo по уже восстановленной доске. */
export const createUndoState = ({
  prevState,
  grid,
  game2048Config,
}: ICreateUndoStateProps): IGame2048State => {
  const playWinState: Game2048PlayWinState = "playing";
  const hasAvailableMoves = grid.canMove();
  const isMaxTileReached = isGridMaxTileReached(grid, game2048Config);
  const history = prevState.history.slice(0, -1);
  const undoAmount = clampUndoAmount({
    undoMax: game2048Config.undoMax,
    amount: prevState.undoAmount - 1,
  });
  const inputLocked = false;

  return {
    ...prevState,
    score: grid.score,
    moves: grid.moves,
    filledTiles: grid.getNotNullTiles(),
    toolMode: "wand",
    undoAmount,
    canContinueAfterWin: false,
    hasAvailableMoves,
    isMaxTileReached,
    playWinState,
    inputLocked,
    history,
    boardSnapshot: createBoardSnapshot({ grid }),
  };
};

interface ICreateContinueStateProps {
  prevState: IGame2048State;
  grid: Game2048GridModel;
  game2048Config: IGameCore2048Config;
}

/** Создает state после решения продолжить игру за пределами первой победы. */
export const createContinueState = ({
  prevState,
  grid,
  game2048Config,
}: ICreateContinueStateProps): IGame2048State => {
  const playWinState: Game2048PlayWinState = "playing";
  const hasAvailableMoves = grid.canMove();
  const isMaxTileReached = isGridMaxTileReached(grid, game2048Config);
  const inputLocked = false;

  return {
    ...prevState,
    filledTiles: grid.getNotNullTiles(),
    canContinueAfterWin: false,
    hasAvailableMoves,
    isMaxTileReached,
    playWinState,
    inputLocked,
    boardSnapshot: createBoardSnapshot({
      grid,
    }),
  };
};

interface ICreateInputUnlockedStateProps {
  prevState: IGame2048State;
  grid: Game2048GridModel;
  game2048Config: IGameCore2048Config;
}

/** Создает state после завершения анимационной блокировки ввода. */
export const createInputUnlockedState = ({
  prevState,
  grid,
  game2048Config,
}: ICreateInputUnlockedStateProps): IGame2048State => {
  const inputLocked = false;

  return {
    ...prevState,
    filledTiles: grid.getNotNullTiles(),
    canContinueAfterWin: canContinueAfterWin({
      playWinState: prevState.playWinState,
      hasAvailableMoves: prevState.hasAvailableMoves,
      isMaxTileReached: prevState.isMaxTileReached,
      game2048Config,
    }),
    inputLocked,
  };
};

interface ICreateToolModeStateProps {
  prevState: IGame2048State;
  toolMode: Game2048ToolMode;
}

/** Создает state после переключения активного инструмента. */
export const createToolModeState = ({
  prevState,
  toolMode,
}: ICreateToolModeStateProps): IGame2048State => {
  return {
    ...prevState,
    toolMode,
  };
};

interface ICalcPlayWinStateProps {
  grid: Game2048GridModel;
  game2048Config: IGameCore2048Config;
}

/**
 * Рассчитывает runtime-состояние партии для внешних потребителей state.
 *
 * `playWinState` нужен UI, менеджеру диалогов и блокировке ввода: `playing` разрешает ходы,
 * `win` просит показать победный диалог, `game-over` просит показать конец партии.
 */
const calcPlayWinState = ({
  grid,
  game2048Config,
}: ICalcPlayWinStateProps): Game2048PlayWinState => {
  const hasAvailableMoves = grid.canMove();
  const maxValue = grid.getMaxValue();
  const isMaxTileReached = maxValue >= game2048Config.maxTileValue;

  /** Финальная плитка важнее первой победы и отсутствия ходов: это отдельный финал партии. */
  if (isMaxTileReached || (!grid.won && maxValue >= game2048Config.winValue)) {
    return "win";
  }

  if (!hasAvailableMoves) {
    return "game-over";
  }

  return "playing";
};

interface ICreateBoardSnapshotProps {
  grid: Game2048GridModel;
  won?: boolean;
}

/** Создает чистый снимок доски с актуальными расходниками. */
const createBoardSnapshot = ({ grid, won }: ICreateBoardSnapshotProps): IHistorySnapshot => {
  const snapshot = grid.createHistorySnapshot();

  return {
    ...snapshot,
    won: won ?? snapshot.won,
  };
};

interface ICalcNextGridWonProps {
  grid: Game2048GridModel;
  playWinState: Game2048PlayWinState;
}

/** Рассчитывает временный `won` для snapshot до синхронизации derived-поля модели. */
const calcNextGridWon = ({ grid, playWinState }: ICalcNextGridWonProps): boolean => {
  return grid.won || playWinState === "win";
};

/** Проверяет достижение финальной плитки текущего сценария. */
const isGridMaxTileReached = (
  grid: Game2048GridModel,
  game2048Config: IGameCore2048Config,
): boolean => {
  return grid.getMaxValue() >= game2048Config.maxTileValue;
};

interface ICanContinueAfterWinProps {
  playWinState: Game2048PlayWinState;
  hasAvailableMoves: boolean;
  isMaxTileReached: boolean;
  game2048Config: IGameCore2048Config;
}

/** Проверяет, доступно ли продолжение после обычной победы. */
const canContinueAfterWin = ({
  playWinState,
  hasAvailableMoves,
  isMaxTileReached,
  game2048Config,
}: ICanContinueAfterWinProps): boolean => {
  return (
    playWinState === "win" &&
    !isMaxTileReached &&
    game2048Config.winValue < game2048Config.maxTileValue &&
    hasAvailableMoves
  );
};

interface IClampHammerAmountProps {
  amount: number;
  hammerMax: number;
}

/** Нормализует количество молотков в границах текущего конфига. */
const clampHammerAmount = ({ hammerMax, amount }: IClampHammerAmountProps): number => {
  const max = Math.max(0, hammerMax);
  return Math.max(0, Math.min(Math.floor(amount), max));
};

interface IClampUndoAmountProps {
  undoMax: number;
  amount: number;
}

/** Нормализует количество undo с учетом безлимитного undoMax = 0. */
const clampUndoAmount = ({ undoMax, amount }: IClampUndoAmountProps): number => {
  const normalized = Math.max(0, Math.floor(amount));
  const max = Math.max(0, Math.floor(undoMax));
  return max === 0 ? normalized : Math.min(normalized, max);
};

interface ICalcHammerAmountAfterMergeRewardsProps {
  prevHammerAmount: number;
  mergeEvents: IGame2048MergeEvent[];
  gameConfig: Game2048Config;
}

/** Считает количество молотков после случайных наград за крупные слияния текущего хода. */
const calcHammerAmountAfterMergeRewards = ({
  prevHammerAmount,
  mergeEvents,
  gameConfig,
}: ICalcHammerAmountAfterMergeRewardsProps): number => {
  let amount = prevHammerAmount;
  for (const event of mergeEvents) {
    if (
      event.value >= gameConfig.hammerTileMin &&
      amount < gameConfig.hammerMax &&
      Math.random() < gameConfig.hammerTileProbability
    ) {
      amount = clampHammerAmount({ hammerMax: gameConfig.hammerMax, amount: amount + 1 });
    }
  }

  return amount;
};

interface ICreateNextHistoryProps {
  prevHistory: IHistorySnapshot[];
  snapshotBeforeAction: IHistorySnapshot;
  undoHistoryDepth: number;
}

/** Добавляет снимок до действия в undo-историю и применяет ограничение глубины истории. */
const createNextHistory = ({
  prevHistory,
  snapshotBeforeAction,
  undoHistoryDepth,
}: ICreateNextHistoryProps): IHistorySnapshot[] => {
  if (undoHistoryDepth === 0) {
    return prevHistory;
  }

  const history = [...prevHistory, snapshotBeforeAction];
  return getHistoryWithLimit(history, undoHistoryDepth);
};

interface IRestoreInitialHistoryProps {
  history?: IHistorySnapshot[];
  undoHistoryDepth: number;
}

/** Восстанавливает стартовую undo-историю из сохранения с учетом глубины истории. */
const restoreInitialHistory = ({
  history,
  undoHistoryDepth,
}: IRestoreInitialHistoryProps): IHistorySnapshot[] => {
  if (!history || undoHistoryDepth === 0) {
    return [];
  }
  return getHistoryWithLimit(history, undoHistoryDepth);
};

function getHistoryWithLimit(history: IHistorySnapshot[], maxSize: number) {
  return history.length > maxSize ? history.slice(-maxSize) : history;
}

interface IInitConsumableProps {
  savedAmount: number;
  startConfigAmount?: number;
  isNewGame: boolean;
}

/** Поднимает имущество новой партии до стартового минимума, не отнимая накопленный остаток. */
const initConsumable = ({
  savedAmount,
  startConfigAmount,
  isNewGame,
}: IInitConsumableProps): number => {
  if (startConfigAmount == null) {
    return 0;
  }

  return isNewGame ? Math.max(startConfigAmount, savedAmount) : savedAmount;
};
