import {
  Game2048,
  type Game2048Config,
  type IGame2048BoardViewConfig,
  normalizeSaveData,
} from "../../common";
import { adService, gameEventBus, saveService } from "../../services";
import { cinderella2048SceneConfig } from "./constants";

interface ICreateCinderella2048GameProps {
  scene: Phaser.Scene;
  boardConfig: IGame2048BoardViewConfig;
  game2048Config: Game2048Config & { readonly undoHistoryDepth: number };
}

/** Создаёт движок 2048 и привязывает к нему настройки Cinderella. */
export function createCinderella2048Game({
  scene,
  boardConfig,
  game2048Config,
}: ICreateCinderella2048GameProps): Game2048 {
  const game = new Game2048({
    scene,
    events: gameEventBus,
    boardConfig,
    spriteConfig: cinderella2048SceneConfig.spriteConfig,
    game2048Config,
    undoHistoryDepth: game2048Config.undoHistoryDepth,
    saveData: normalizeSaveData(saveService.get()),
    onRestartClick: () => scene.scene.restart(),
    onSave: (state) => saveService.save(state),
  });

  addRewardAdResultEvents(game);
  addAdsForNewGameEvents();
  addAdsForContinueAfterWinEvents();

  return game;
}

/** Переводит результат rewarded-рекламы в подтверждённую игровую награду. */
function addRewardAdResultEvents(game: Game2048): void {
  gameEventBus.on("onRewardAdClosed", (result) => {
    if (!result.wasShown) {
      game.emitEndState();
      return;
    }

    if (result.rewardType !== "undo" && result.rewardType !== "hammer") {
      return;
    }

    gameEventBus.emit("game2048RewardGranted", { rewardType: result.rewardType });
  });
}

/** Пропускает новую игру через полноэкранную рекламу, когда она доступна. */
function addAdsForNewGameEvents(): void {
  gameEventBus.on("game2048NewGameClick", () => {
    if (!adService.isFullAdEnabled) {
      gameEventBus.emit("game2048NewGameRequest");
      return;
    }

    gameEventBus.once("onCommonAdClosed", () => {
      gameEventBus.emit("game2048NewGameRequest");
    });
    gameEventBus.emit("requestCommonAd");
  });
}

/** Пропускает продолжение после победы через полноэкранную рекламу. */
function addAdsForContinueAfterWinEvents(): void {
  gameEventBus.on("game2048ContinueClick", () => {
    if (!adService.isFullAdEnabled) {
      gameEventBus.emit("game2048ContinueRequest");
      return;
    }

    gameEventBus.once("onCommonAdClosed", () => {
      gameEventBus.emit("game2048ContinueRequest");
    });
    gameEventBus.emit("requestCommonAd");
  });
}
