import { game2048CoreConfig } from "./constants";
import { Game2048TileModel } from "./TileModel";
import { createMatrix, pickRandom } from "./utils";
import { MoveDirection } from "./types";
import type {
  IGame2048Cell,
  IGame2048MergeEvent,
  IGame2048MoveResult,
  IGame2048TileMotion,
  IHistoryRows,
  IHistorySnapshot,
  ITileMergePolicy,
  ITileSpawnPolicy,
  TileSpawnReason,
} from "./types";

interface IProcessGame2048LineProps {
  cells: IGame2048Cell[];
  newGrid: Array<Array<Game2048TileModel | null>>;
  mergeEvents: IGame2048MergeEvent[];
  mergeTargetIds: number[];
  tileMotions: IGame2048TileMotion[];
}

interface IGridModelProps {
  size: number;
  tileMergePolicy: ITileMergePolicy;
  tileSpawnPolicy: ITileSpawnPolicy;
}

/** Управляет квадратной сеткой, правилами 2048 и счетом. */
export class Game2048GridModel {
  /** Текущая матрица плиток поля. */
  grid: Array<Array<Game2048TileModel | null>>;

  /** Счет текущей партии. */
  score: number;

  /** Количество успешных ходов в текущей партии. */
  moves: number;

  /** Факт достижения победной плитки на этой доске; не означает, что сейчас открыт экран победы. */
  won: boolean;

  private get size() {
    return this.props.size;
  }

  /** Создает игровое поле указанного размера. */
  constructor(private readonly props: IGridModelProps) {
    this.grid = this.createEmptyGrid();
    this.score = 0;
    this.moves = 0;
    this.won = false;
    this.reset();
  }

  /** Считает количество занятых плитками клеток на текущем поле. */
  getFillAmount() {
    let count = 0;
    this.forEachTile(() => {
      count += 1;
    });
    return count;
  }

  /** Полностью сбрасывает поле и добавляет стартовые плитки. */
  reset(): void {
    this.grid = this.createEmptyGrid();
    this.score = 0;
    this.moves = 0;
    this.won = false;

    for (let index = 0; index < game2048CoreConfig.startTiles; index += 1) {
      this.addRandomTile("initial");
    }
  }

  /** Проверяет, находится ли клетка внутри поля. */
  isInside(row: number, col: number): boolean {
    return row >= 0 && row < this.size && col >= 0 && col < this.size;
  }

  /** Возвращает плитку в заданной клетке. */
  getTile(row: number, col: number): Game2048TileModel | null {
    if (!this.isInside(row, col)) {
      return null;
    }

    return this.grid[row][col];
  }

  /** Возвращает список всех пустых клеток. */
  getEmptyCells(): IGame2048Cell[] {
    const cells: IGame2048Cell[] = [];

    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        if (this.grid[row][col] === null) {
          cells.push({ row, col });
        }
      }
    }

    return cells;
  }

  /** Добавляет новую плитку в случайную пустую клетку по правилам текущего сценария. */
  addRandomTile(reason: TileSpawnReason): Game2048TileModel | undefined {
    const emptyCells = this.getEmptyCells();
    const cell = pickRandom(emptyCells);

    if (!cell) {
      return;
    }

    const value = this.props.tileSpawnPolicy.getTileValue(reason);
    const tile = new Game2048TileModel({ value, row: cell.row, col: cell.col });
    this.grid[cell.row][cell.col] = tile;

    return tile;
  }

  /** Создает чистый снимок поля для истории undo и сохранения партии. */
  createHistorySnapshot(): IHistorySnapshot {
    const rows: IHistoryRows = [];

    for (let row = 0; row < this.size; row += 1) {
      rows[row] = [];

      for (let col = 0; col < this.size; col += 1) {
        const tile = this.grid[row][col];
        rows[row][col] = tile ? tile.toHistoryData() : null;
      }
    }

    return {
      grid: rows,
      score: this.score,
      moves: this.moves,
      won: this.won,
    };
  }

  /** Восстанавливает поле из чистого снимка истории. */
  restoreHistorySnapshot(snapshot: IHistorySnapshot): void {
    this.grid = this.createEmptyGrid();
    this.score = snapshot.score;
    this.moves = snapshot.moves;
    this.won = snapshot.won;

    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        const tileData = snapshot.grid[row][col];

        if (tileData) {
          this.grid[row][col] = Game2048TileModel.fromHistoryData({
            data: tileData,
            row,
            col,
          });
        }
      }
    }
  }

  /** Выполняет ход в выбранном направлении. */
  move(direction: MoveDirection): IGame2048MoveResult {
    const lines = this.getLinesForDirection(direction);
    const newGrid = this.createEmptyGrid();
    const mergeEvents: IGame2048MergeEvent[] = [];
    const mergeTargetIds: number[] = [];
    const tileMotions: IGame2048TileMotion[] = [];
    let totalScore = 0;
    let moved = false;

    if (lines.length === 0) {
      return { moved: false, scoreGained: 0, mergeEvents, tileMotions, mergeTargetIds };
    }

    for (const line of lines) {
      const lineResult = this.processLine({
        cells: line,
        newGrid,
        mergeEvents,
        mergeTargetIds,
        tileMotions,
      });
      moved = moved || lineResult.moved;
      totalScore += lineResult.scoreGained;
    }

    if (!moved) {
      return { moved: false, scoreGained: 0, mergeEvents, tileMotions, mergeTargetIds };
    }

    this.grid = newGrid;
    this.score += totalScore;
    this.moves += 1;

    return { moved: true, scoreGained: totalScore, mergeEvents, tileMotions, mergeTargetIds };
  }

  /** Удаляет плитку из клетки как успешный ход специального инструмента. */
  removeTile(row: number, col: number): boolean {
    if (!this.isInside(row, col) || !this.grid[row][col]) {
      return false;
    }

    this.grid[row][col] = null;
    this.moves += 1;

    return true;
  }

  /** Проверяет, есть ли хотя бы один доступный ход. */
  canMove(): boolean {
    return this.getEmptyCells().length > 0 || this.hasEqualNeighbor();
  }

  /** Возвращает максимальное значение на поле. */
  getMaxValue(): number {
    let max = 0;

    this.forEachTile((tile) => {
      if (tile.value > max) {
        max = tile.value;
      }
    });

    return max;
  }

  /** Выполняет функцию для каждой плитки на поле. */
  forEachTile(callback: (tile: Game2048TileModel) => void): void {
    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        const tile = this.grid[row][col];

        if (tile) {
          callback(tile);
        }
      }
    }
  }

  getNotNullTiles(): number {
    let i = 0;
    this.forEachTile((_) => i++);
    return i;
  }

  /** Создает пустую матрицу поля. */
  private createEmptyGrid(): Array<Array<Game2048TileModel | null>> {
    return createMatrix<Game2048TileModel | null>(this.size, null);
  }

  /** Строит линии обхода поля для заданного направления. */
  private getLinesForDirection(direction: MoveDirection): IGame2048Cell[][] {
    const lines: IGame2048Cell[][] = [];

    switch (direction) {
      case MoveDirection.left: {
        for (let row = 0; row < this.size; row += 1) {
          const line: IGame2048Cell[] = [];

          for (let col = 0; col < this.size; col += 1) {
            line.push({ row, col });
          }

          lines.push(line);
        }
        break;
      }
      case MoveDirection.right: {
        for (let row = 0; row < this.size; row += 1) {
          const line: IGame2048Cell[] = [];

          for (let col = this.size - 1; col >= 0; col -= 1) {
            line.push({ row, col });
          }

          lines.push(line);
        }
        break;
      }
      case MoveDirection.up: {
        for (let col = 0; col < this.size; col += 1) {
          const line: IGame2048Cell[] = [];

          for (let row = 0; row < this.size; row += 1) {
            line.push({ row, col });
          }

          lines.push(line);
        }
        break;
      }
      case MoveDirection.down: {
        for (let col = 0; col < this.size; col += 1) {
          const line: IGame2048Cell[] = [];

          for (let row = this.size - 1; row >= 0; row -= 1) {
            line.push({ row, col });
          }

          lines.push(line);
        }
        break;
      }
    }
    return lines;
  }

  /** Сжимает и объединяет одну линию поля. */
  private processLine(props: IProcessGame2048LineProps): {
    moved: boolean;
    scoreGained: number;
  } {
    const tiles = this.collectTilesFromLine(props.cells);
    const placed: Game2048TileModel[] = [];
    const mergedTileIds = new Set<number>();
    let moved = false;
    let scoreGained = 0;

    for (const tile of tiles) {
      const startRow = tile.row;
      const startCol = tile.col;
      const previous = placed.length > 0 ? placed[placed.length - 1] : null;

      if (
        previous &&
        this.props.tileMergePolicy.canMerge(previous.value, tile.value) &&
        !mergedTileIds.has(previous.id)
      ) {
        const value = previous.value;
        const nextValue = value * 2;
        const toRow = previous.row;
        const toCol = previous.col;

        tile.setPosition(toRow, toCol);
        previous.value = nextValue;
        mergedTileIds.add(previous.id);
        moved = true;
        scoreGained += nextValue;
        props.mergeEvents.push({ row: toRow, col: toCol, value: nextValue });
        props.tileMotions.push({
          tileId: tile.id,
          toRow,
          toCol,
        });
        props.mergeTargetIds.push(previous.id);
      } else {
        const targetCell = props.cells[placed.length];
        tile.setPosition(targetCell.row, targetCell.col);

        if (startRow !== tile.row || startCol !== tile.col) {
          moved = true;
          props.tileMotions.push({
            tileId: tile.id,
            toRow: tile.row,
            toCol: tile.col,
          });
        }

        placed.push(tile);
      }
    }

    for (const tile of placed) {
      props.newGrid[tile.row][tile.col] = tile;
    }

    return { moved, scoreGained };
  }

  /** Собирает существующие плитки из линии в порядке движения. */
  private collectTilesFromLine(cells: IGame2048Cell[]): Game2048TileModel[] {
    const tiles: Game2048TileModel[] = [];

    for (const cell of cells) {
      const tile = this.grid[cell.row][cell.col];

      if (tile) {
        tiles.push(tile);
      }
    }

    return tiles;
  }

  /** Проверяет наличие соседних плиток, которые можно объединить по текущей политике слияния. */
  private hasEqualNeighbor(): boolean {
    for (let row = 0; row < this.size; row += 1) {
      for (let col = 0; col < this.size; col += 1) {
        const tile = this.grid[row][col];

        if (!tile) {
          continue;
        }

        const right = this.getTile(row, col + 1);
        const down = this.getTile(row + 1, col);

        if (
          (right && this.props.tileMergePolicy.canMerge(tile.value, right.value)) ||
          (down && this.props.tileMergePolicy.canMerge(tile.value, down.value))
        ) {
          return true;
        }
      }
    }

    return false;
  }
}
