import { getAtlasImgAsset, getFontFamilyAsset } from "../../autoAssetHelpers";
import { createSharedUiInfoBlock } from "../../common/ui/2026-06-cind-block";
import { fitToSize, vpx } from "../../common";

interface IProps {
  scene: Phaser.Scene;
  title: string;
  initValue: string;
  fontSize?: number;
}

/** в value принимает число сам форматирует **/
export function createCindUiInfo({ scene, title, initValue }: IProps) {
  const bgAsset = getAtlasImgAsset("uiInfoFrame");
  const cssColor = "#A2525B";
  const gap = 0;

  const titleStyle: Phaser.Types.GameObjects.Text.TextStyle = {
    fontFamily: getFontFamilyAsset("georgiaRegular"),
    fontSize: "28px",
    color: cssColor,
  };

  const valueStyle: Phaser.Types.GameObjects.Text.TextStyle = {
    fontFamily: getFontFamilyAsset("interSemibold"),
    fontSize: "24px",
    fontStyle: "bold",
    color: cssColor,
  };

  const view = createSharedUiInfoBlock({
    scene,
    bgAsset,
    title,
    initValue,
    titleStyle,
    valueStyle,
    gap,
  });

  fitToSize({
    gameObject: view,
    width: vpx(152),
    height: vpx(140),
  });

  return view;
}
