import { game2048CoreConfig } from "./constants";
import type { Game2048StageValue } from "./constants";
import type { IGameCore2048Config, ITileSpawnPolicy, TileSpawnReason } from "./types";

interface ICreateTileSpawnPolicyProps {
  game2048Config: IGameCore2048Config;
}

interface IGetNextStageValueProps {
  stageValue: Game2048StageValue;
  maxTileValue: number;
}

/** Создает политику спавна плиток для выбранного сценария партии. */
export function createTileSpawnPolicy(props: ICreateTileSpawnPolicyProps): ITileSpawnPolicy {
  const { game2048Config } = props;
  const stageValue = resolveStartStageValue(game2048Config.startStageValue);
  const nextStageValue = getNextStageValue({
    stageValue,
    maxTileValue: game2048Config.maxTileValue,
  });

  return {
    getTileValue: (reason) => getTileValueByReason({
      reason,
      stageValue,
      nextStageValue,
    }),
  };
}

/** Возвращает поддерживаемый стартовый этап или самый первый этап при ошибке в конфиге. */
function resolveStartStageValue(value: number): Game2048StageValue {
  const stageValue = game2048CoreConfig.supportedValues.find((supportedValue) => supportedValue === value);

  if (stageValue) {
    return stageValue;
  }

  return game2048CoreConfig.supportedValues[0] as Game2048StageValue;
}

/** Возвращает следующий этап, если он поддержан ассетами и не выходит за максимум сценария. */
function getNextStageValue(props: IGetNextStageValueProps): Game2048StageValue | undefined {
  const stageIndex = game2048CoreConfig.supportedValues.indexOf(props.stageValue);
  const nextStageValue = game2048CoreConfig.supportedValues[stageIndex + 1] as Game2048StageValue | undefined;

  if (!nextStageValue || nextStageValue > props.maxTileValue) {
    return undefined;
  }

  return nextStageValue;
}

/** Выбирает значение плитки: на старте N или N+1, после хода только N. */
function getTileValueByReason(props: {
  reason: TileSpawnReason;
  stageValue: Game2048StageValue;
  nextStageValue?: Game2048StageValue;
}): number {
  if (props.reason === "move" || !props.nextStageValue) {
    return props.stageValue;
  }

  return Math.random() < game2048CoreConfig.initialBaseTileChance
    ? props.stageValue
    : props.nextStageValue;
}
