import { AlignObject, cssColorToInt } from "@kvisaz/phaser-sugar";
import { ImageFrameData } from "../../game-core";

const SCENE_ERROR = "makeView scene == null error: check you dont use makeView inside makeView!";

class ObjectBuilder {
  private scene?: Phaser.Scene;

  setScene(scene: Phaser.Scene) {
    this.scene = scene;
  }

  clear() {
    this.scene = undefined;
  }

  img({ textureName, frameName }: ImageFrameData) {
    if (this.scene == null) throw SCENE_ERROR;
    return this.scene.add.image(0, 0, textureName, frameName);
  }

  nine({
    textureName,
    frameName,
    width,
    height,
    padding,
  }: {
    textureName: string;
    frameName?: string;
    width?: number;
    height?: number;
    padding?: number;
  }) {
    if (this.scene == null) throw SCENE_ERROR;
    return this.scene.add.nineslice(
      0,
      0,
      textureName,
      frameName,
      width,
      height,
      padding,
      padding,
      padding,
      padding,
    );
  }

  text({
    text,
    style = {},
  }: {
    text: string | number;
    style?: Phaser.Types.GameObjects.Text.TextStyle;
  }) {
    if (this.scene == null) throw SCENE_ERROR;
    return this.scene.add.text(0, 0, "" + text, style);
  }

  circle(props: { color: string, size: number, strokeColor?: string, strokeWidth?: number }): Phaser.GameObjects.Arc{
    if (this.scene == null) throw SCENE_ERROR;
    const circle = this.scene.add.circle(0, 0, props.size, cssColorToInt(props.color));
    if(props.strokeWidth && props.strokeColor){
      circle.setStrokeStyle(props.strokeWidth, cssColorToInt(props.strokeColor))
    }
    return  circle;
  }

  rect(props: { color: string, width: number, height: number, strokeColor?: string, strokeWidth?: number }): Phaser.GameObjects.Rectangle {
    if (this.scene == null) throw SCENE_ERROR;

    const rect = this.scene.add.rectangle(0, 0, props.width, props.height, cssColorToInt(props.color));
    if(props.strokeWidth && props.strokeColor){
      rect.setStrokeStyle(props.strokeWidth, cssColorToInt(props.strokeColor))
    }
    return  rect;
  }

  con<T extends Phaser.GameObjects.GameObject>(children: T[]) {
    if (this.scene == null) throw SCENE_ERROR;
    return this.scene.add.container(0, 0, children);
  }
}

const reusableBuilder = new ObjectBuilder();

/** создает view
 * - которое можно использовать в цепочках макетирования
 * - либо обычный объект Phaser
 * - либо ArrayAlignObject (но для удобной работы можно и Phaser.Container
 * **/
export function makeView<T extends AlignObject>(
  scene: Phaser.Scene,
  make: (builder: ObjectBuilder) => T,
) {
  reusableBuilder.setScene(scene);
  const result = make(reusableBuilder);
  reusableBuilder.clear();
  return result;
}
