import { makeAlign } from "@kvisaz/phaser-sugar";
import { getAtlasImgAsset } from "../../../autoAssetHelpers";
import { vpx } from "../../../common";
import { createCindTextButton } from "../../../view-elements/ui/createCindTextButton";
import { createDialogTexts } from "../../../view-elements/ui/createDialogTexts";
import { getLocalizedText } from "../../../view-elements/locale";
import { hammerInfoCardConfig } from "./constants";

export interface IHammerInfoCardViewProps {
  scene: Phaser.Scene;
  onRemoveClick: () => void;
}

/** Отображает компактную информационную карточку активного молотка. */
export class HammerInfoCardView extends Phaser.GameObjects.Container {
  /** Создает карточку с компоновкой, согласованной с игровыми диалогами. */
  constructor({ scene, onRemoveClick }: IHammerInfoCardViewProps) {
    super(scene);

    const backgroundAsset = getAtlasImgAsset("frame03Nine90");
    const background = scene.add.nineslice(
      0,
      0,
      backgroundAsset.textureName,
      backgroundAsset.frameName,
      vpx(hammerInfoCardConfig.width),
      vpx(hammerInfoCardConfig.height),
      vpx(hammerInfoCardConfig.backgroundPadding),
      vpx(hammerInfoCardConfig.backgroundPadding),
      vpx(hammerInfoCardConfig.backgroundPadding),
      vpx(hammerInfoCardConfig.backgroundPadding),
    );
    const title = createDialogTexts({
      scene,
      text: getLocalizedText("hammerInfoCardTitle"),
      type: "title",
      maxWidthPx: vpx(hammerInfoCardConfig.width),
    });
    const message = createDialogTexts({
      scene,
      text: getLocalizedText("hammerInfoCardMessage"),
      type: "info",
      maxWidthPx: vpx(hammerInfoCardConfig.width),
    });
    const removeButton = createCindTextButton({
      scene,
      text: getLocalizedText("hammerInfoCardRemove"),
      type: "primary",
      onClick: onRemoveClick,
    });

    /** Повторяем вертикальный ритм диалогов, но уплотняем его под меньшую карточку. */
    makeAlign((align) => {
      align
        .anchor(background)
        .centerX(title)
        .topIn(title, vpx(hammerInfoCardConfig.titleTopOffset));
      align
        .anchor(title)
        .centerX(message)
        .bottomTo(message, vpx(hammerInfoCardConfig.messageGap));
      align
        .anchor(background)
        .centerX(removeButton)
        .bottomIn(removeButton, -vpx(hammerInfoCardConfig.buttonBottomOffset));
    });

    this.add([background, title, message, removeButton]);
    scene.add.existing(this);
  }
}
