import { SDK } from "ysdk";
import { IAdService } from "./types";
import { MockAdService } from "./MockAdService";
import { YandexAdService } from "./YandexAdService";
import { getErrorMessage } from "../../string";
import { MinimalTimeIntervalStrategy } from "../utils/MinimalTimeIntervalStrategy";

interface IGameAdManagerProps {
  isMockAd?: boolean;
  adCooldownMs: number;
}

/** Управляет рекламным сервисом, cooldown-ами и безопасным запуском рекламных показов. */
export class AdsService {
  private readonly timeLogic: MinimalTimeIntervalStrategy;
  private adService?: IAdService;

  constructor(private readonly props: IGameAdManagerProps) {
    this.timeLogic = new MinimalTimeIntervalStrategy(props.adCooldownMs);
  }

  get isFullAdEnabled(): boolean {
    return this.adService != null && this.timeLogic.isAllowed();
  }

  /** нет ограничений на время **/
  get isRewardAdEnabled(): boolean {
    return this.adService != null;
  }

  /** Инициализирует runtime ad service и запускает отсчет cooldown-ов. */
  preload(sdk: SDK|undefined): void {
    if (this.adService != null) return;
    if (this.props.isMockAd) {
      this.adService = new MockAdService();
    } else {
      this.adService = sdk ? new YandexAdService(sdk) : undefined;
    }
    /** Яндекс показывате рекламу при старте так что отмечаем **/
    this.timeLogic.markTime();
  }

  /** Показывает fullscreen-рекламу с учетом доступности сервиса и cooldown-а. */
  showCommonAd(onClose?: (args: { wasShown: boolean; error?: string }) => void): void {
    try {
      if (!this.adService) {
        onClose?.({ wasShown: false, error: "adService not available" });
        return;
      }
      if (!this.isFullAdEnabled) {
        onClose?.({ wasShown: false, error: "ad is not allowed yet" });
        return;
      }
      const mark = () => this.timeLogic.markTime();
      this.adService.showCommonAd({
        onOpen: mark,
        onClose: (args) => {
          if (args.wasShown) {
            mark();
          }
          onClose?.(args);
        },
      });
    } catch (e) {
      onClose?.({ wasShown: false, error: getErrorMessage(e) });
    }
  }

  /**
   * Показывает rewarded-рекламу с учетом доступности сервиса
   * cooldown не требуются
   *  */
  showRewardedAd(
    onClose?: (args: { wasShown: boolean; error?: string; isReward: boolean }) => void,
  ): void {
    try {
      if (!this.adService || !this.isRewardAdEnabled) {
        onClose?.({ wasShown: false, isReward: false, error: "ad not available" });
        return;
      }
      this.adService.showRewardedAd({
        onClose: (args) => {
          onClose?.(args);
        },
      });
    } catch (e) {
      onClose?.({ wasShown: false, error: getErrorMessage(e), isReward: false });
    }
  }
}
