import { makeAlign } from "@kvisaz/phaser-sugar";
import { makeView } from "../../gameObjects/makeView/makeView";
import { column, onDestroy, safeArray } from "../../index";
import { ImageFrameData } from "../../game-core";
import { onValueData } from "./setValueData";

interface IProps {
  scene: Phaser.Scene;
  initValue: string; // основной текст
  valueStyle: Phaser.Types.GameObjects.Text.TextStyle;
  title?: string; // выводится сверху если задан
  titleStyle?: Phaser.Types.GameObjects.Text.TextStyle;
  gap?: number; // расстояние между титлом и текстом есть есть
  bgAsset: ImageFrameData;
}

/**
 *  возвращает просто одно/двухрядный инфоблок
 *  с выводом стилей для каждого ряда
 *
 *  обновлять - через setData('value', someString)
 *  обновление стиля не предусмотрено
 **/
export function createSharedUiInfoBlock({
  scene,
  title,
  initValue,
  valueStyle,
  titleStyle = valueStyle,
  bgAsset,
  gap,
}: IProps) {
  return makeView(scene, (builder) => {
    const label = initValue;

    const bg = builder.img(bgAsset);

    const titleText =
      title != null
        ? builder.text({
            text: title,
            style: titleStyle,
          })
        : undefined;

    const valueText = builder.text({
      text: label,
      style: valueStyle,
    });

    const con = builder.con(safeArray([bg, titleText, valueText]));

    const layout = () => {
      makeAlign((align) => {
        const contentRow =
          titleText != null ? column([titleText, valueText], { nextOffsetY: gap }) : valueText;
        align.anchor(bg).center(contentRow);
      });
    };

    const updateValue = (value: string) => {
      valueText.setText(value);
      layout();
    };

    updateValue(initValue);
    layout();

    /** Обязательно ставим value прежде чем слушать **/
    con.setData("value", initValue);
    const unSubState = onValueData<string>(con, updateValue);

    const destroy = () => {
      unSubState();
    };

    onDestroy(con, destroy);
    return con;
  });
}
