import { type InstantDataService, LocalDataService, type SaveResult } from "../../index";

interface ISaveServiceProps {
  appId: string;
  dataKey: string;
}

/**
 * Хранит один JSON-снимок прогресса игры в облаке или localStorage.
 * Удобный универсальный хранитель данных
 * не зависящий от игры
 * */
export class SaveService {
  private data?: unknown;
  private localService: InstantDataService;
  private cloudService?: InstantDataService;

  /**
   * Облачный сервис при наличии имеет безусловный приоритет
   * не может и не должен локальный сервис который легко взломать
   * замещать собой результаты игры
   * **/
  private get service() {
    return this.cloudService ?? this.localService;
  }

  /** Создает сервис сохранения с ключом текущей версии игры. */
  constructor(private props: ISaveServiceProps) {
    this.localService = new LocalDataService({ appId: props.appId });
  }

  /**
   * Загружает сохранение до запуска игровой сцены.
   * облачный сервис лучше передать здесь - если он готов
   *  */
  async preload(cloudService: InstantDataService | undefined): Promise<void> {
    this.cloudService = cloudService;

    const { service } = this;
    const { dataKey } = this.props;
    await service.preload();
    this.data = await service.getData(dataKey);
  }

  /** Возвращает загруженное состояние, если оно есть. */
  get<T>(): T | undefined {
    return this.data as T | undefined;
  }

  /**
   * Сохраняет состояние игры в активное хранилище в памяти
   * - делает попытку сохранения в облачное/локальное
   * - используйте SaveResult чтобы убедиться в облачном/локальном сохранении
   * или дождаться следующего окна для записи если timeToNextSave != null && timeToNextSave > 0
   *  */
  async save<T>(state: T, immediatelySave?: boolean): Promise<SaveResult> {
    this.data = state;
    const { service, props } = this;
    const { dataKey } = props;
    return await service.setData(dataKey, state, immediatelySave);
  }
}
