interface IProps<TValue> {
  obj: Phaser.GameObjects.GameObject,
  dataKey: string,
  callback: (value: TValue, previousValue: TValue, obj: Phaser.GameObjects.GameObject) => void,
}

/**
 * слушает изменения дата с ключом
 * con.setData("value", 123);
 *
 * внимание ключе уже должен быть установлен
 * тк первый setData не работает
 * **/
export function onGameObjectDataKeyChange<TValue>({ obj, dataKey, callback }: IProps<TValue>): () => void {
  const eventName = `changedata-${dataKey}`;

  const handler = (
    gameObject: Phaser.GameObjects.GameObject,
    value: TValue,
    previousValue: TValue,
  ) => {
    callback(value, previousValue, gameObject);
  };

  obj.on(eventName, handler);

  return () => {
    obj.off(eventName, handler);
  };
}
