type PEConfig = Phaser.Types.GameObjects.Particles.ParticleEmitterConfig;

const defaultFireworksConfig = {
  emitterYRatio: 0.6,
  particleOptions: {
    lifespan: { min: 1200, max: 2000 },
    speed: { min: 600, max: 1000 },
    scale: { start: 1, end: 1.2 },
    rotate: { start: 0, end: 360 },
    gravityY: 380,
    frequency: 1200,
    quantity: 6,
    emitting: false,
  },
};

export interface IFireworksEffectProps {
  scene: Phaser.Scene;
  textureName: string;
  frameNames: string[];
  /** Вертикальная позиция эмиттеров как доля высоты сцены. */
  emitterYRatio?: number;
  leftAngle?: { min: number, max: number };
  rightAngle?: { min: number, max: number };
  particleOptions?: Partial<PEConfig>;
}

/** Управляет парой симметричных эмиттеров праздничного салюта. */
export class FireworksEffect {
  protected readonly props: IFireworksEffectProps;
  readonly leftEmitter: Phaser.GameObjects.Particles.ParticleEmitter;
  readonly rightEmitter: Phaser.GameObjects.Particles.ParticleEmitter;
  private stopTimer?: Phaser.Time.TimerEvent;

  /** Создает выключенные эмиттеры с общими настройками частиц. */
  constructor(props: IFireworksEffectProps) {
    this.props = props;
    const { scene, textureName, frameNames, particleOptions, leftAngle, rightAngle } = props;

    const commonConfig: PEConfig = {
      frame: frameNames,
      ...defaultFireworksConfig.particleOptions,
      ...particleOptions,
    };

    const emitterY = this.getEmitterY();

    this.leftEmitter = scene.add.particles(0, emitterY, textureName, {
      ...commonConfig,
      angle: leftAngle ?? { min: 270, max: 330 },
    });

    this.rightEmitter = scene.add.particles(scene.scale.width, emitterY, textureName, {
      ...commonConfig,
      angle: rightAngle ?? { min: 210, max: 270 },
    });
  }

  /** Отменяет отложенную остановку и уничтожает оба эмиттера. */
  destroy(): void {
    this.clearStopTimer();
    this.leftEmitter.destroy();
    this.rightEmitter.destroy();
  }

  /** Запускает непрерывный салют и отменяет прежнюю отложенную остановку. */
  start(): void {
    this.clearStopTimer();
    this.updatePositions();
    this.leftEmitter.start();
    this.rightEmitter.start();
  }

  /** Запускает салют и останавливает эмиссию через указанное время. */
  startFor(durationMs: number): void {
    this.start();
    this.stopTimer = this.props.scene.time.delayedCall(durationMs, () => {
      this.stopTimer = undefined;
      this.stop();
    });
  }

  /** Отменяет таймер и прекращает создание новых частиц. */
  stop(): void {
    this.clearStopTimer();
    this.leftEmitter.stop();
    this.rightEmitter.stop();
  }

  /** Обновляет позиции эмиттеров по актуальным размерам сцены. */
  protected updatePositions(): void {
    const { scene } = this.props;
    const emitterY = this.getEmitterY();
    this.leftEmitter.setPosition(0, emitterY);
    this.rightEmitter.setPosition(scene.scale.width, emitterY);
  }

  /** Рассчитывает вертикальную координату эмиттеров из доли высоты сцены. */
  protected getEmitterY(): number {
    const { scene, emitterYRatio = defaultFireworksConfig.emitterYRatio } = this.props;
    return scene.scale.height * emitterYRatio;
  }

  /** Удаляет активный таймер короткого режима, если он был создан. */
  private clearStopTimer(): void {
    this.stopTimer?.remove(false);
    this.stopTimer = undefined;
  }
}
