import { game2048Config } from "./config.game2048";
import {
  getUrlParam,
  isAllowedHost,
  SaveService,
  TypedEventsEmitter,
  YandexDataService,
  YandexSdkWrapperV2,
} from "./common";
import { AdsService } from "./common/services/ads";
import { IGameEvents } from "./events";
import { ICommonAdEvents } from "./common/scenes-layers/AdsOverlayManager/events";

export type AllGameEvents = IGameEvents & ICommonAdEvents;

/** Yandex SDK Wrapper */
export const yandexSdkWrapper = new YandexSdkWrapperV2({
  isLogging: game2048Config.isDebugLogging,
});

/** Общий сервис сохранения текущего игрового состояния. */
export const saveService = new SaveService({
  appId: game2048Config.saveAppId,
  dataKey: game2048Config.saveDataKey,
});

/** рекламный сервис **/
export const adService = new AdsService({
  isMockAd: isMockAdEnabled(),
  adCooldownMs: game2048Config.adCooldownMs,
});

/**
 * Общийи инициализатор, первым должен идти ysdk или его попытка детекции
 * ставь в BootScene
 *  */
export async function preloadServices(): Promise<void> {
  try {
    await yandexSdkWrapper.init();
    const yandexPlayer = yandexSdkWrapper.getPlayer();
    const cloudSaveService = yandexPlayer != null ? new YandexDataService(yandexPlayer) : undefined;
    adService.preload(yandexSdkWrapper.getSDK());
    await saveService.preload(cloudSaveService);
  } catch (e) {
    console.warn(e);
  }
}

/** Общая шина эвентов */
export const gameEventBus = new TypedEventsEmitter<AllGameEvents>();

/**
 * Настройка моков
 */
function isMockDomain() {
  const ALLOWED_URL_STARTS = ["localhost", "kvisaz.github.io"];
  return isAllowedHost(ALLOWED_URL_STARTS);
}

function isMockAdEnabled() {
  return isMockDomain() && getUrlParam("mockAd") !== null;
}

function isMockShopEnabled() {
  return isMockDomain() && getUrlParam("mockShop") !== null;
}
