import { game2048CoreConfig } from "./constants";
import type { IHistorySnapshot, IHistoryTile } from "./types";

interface IIsValidTileSnapshotShapeProps {
  value: unknown;
}

/** Проверяет, что значение является обычным объектом для runtime-валидации сохранения. */
function isRecord(value: unknown): value is Record<string, unknown> {
  return value != null && typeof value === "object" && !Array.isArray(value);
}

/** Проверяет, что число является конечным целым числом не меньше нуля. */
function isNonNegativeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 0;
}

/** Проверяет, что число является положительным целым идентификатором плитки. */
function isPositiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value > 0;
}

/** Проверяет, что значение плитки поддержано правилами и ассетами текущей игры. */
function isSupportedTileValue(value: unknown): value is number {
  return (
    typeof value === "number" &&
    game2048CoreConfig.supportedValues.some((supportedValue) => supportedValue === value)
  );
}

/** Проверяет форму сериализованной плитки. */
function isValidTileSnapshotShape(props: IIsValidTileSnapshotShapeProps): props is IIsValidTileSnapshotShapeProps & {
  value: IHistoryTile;
} {
  const { value } = props;

  if (!isRecord(value)) {
    return false;
  }

  const { id, value: tileValue } = value;

  if (!isPositiveInteger(id)) {
    return false;
  }

  if (!isSupportedTileValue(tileValue)) {
    return false;
  }

  return true;
}

/** Проверяет, что данные можно безопасно восстановить как чистый снимок истории. */
export function isValidHistorySnapshot(snapshot: unknown): snapshot is IHistorySnapshot {
  if (!isRecord(snapshot)) {
    return false;
  }

  const { grid, score, moves, won, hammerAmount, undoAmount } = snapshot;
  const gridSize = game2048CoreConfig.gridSize;

  if (!Array.isArray(grid) || grid.length !== gridSize) {
    return false;
  }

  if (!isNonNegativeInteger(score) || !isNonNegativeInteger(moves)) {
    return false;
  }

  if (typeof won !== "boolean") {
    return false;
  }

  if (hammerAmount !== undefined && !isNonNegativeInteger(hammerAmount)) {
    return false;
  }

  if (undoAmount !== undefined && !isNonNegativeInteger(undoAmount)) {
    return false;
  }

  const usedTileIds = new Set<number>();

  for (let row = 0; row < gridSize; row += 1) {
    const snapshotRow = grid[row];

    if (!Array.isArray(snapshotRow) || snapshotRow.length !== gridSize) {
      return false;
    }

    for (let col = 0; col < gridSize; col += 1) {
      const tile = snapshotRow[col];

      if (tile === null) {
        continue;
      }

      const tileProps = { value: tile };

      if (!isValidTileSnapshotShape(tileProps)) {
        return false;
      }

      if (usedTileIds.has(tileProps.value.id)) {
        return false;
      }

      usedTileIds.add(tileProps.value.id);
    }
  }

  return true;
}
