import { autoAssetsConfig } from "./autoAssetsConfig";

export type AutoAssetImage = keyof typeof autoAssetsConfig.images;

export function getAtlasImgAsset(key: AutoAssetImage){
  const asset: { url: string, frameName?: string } = autoAssetsConfig.images[key];

  return {
    textureName: asset.url,
    frameName: asset.frameName
  }
}


export function getFontFamilyAsset(key: keyof typeof autoAssetsConfig.fonts){
  return getFontAsset(key).fontFamily
}

function getFontAsset(key: keyof typeof autoAssetsConfig.fonts){
  const asset = autoAssetsConfig.fonts[key];

  return {
    url: asset.url,
    name: asset.name,
    fontFamily: asset.fontFamily
  }
}

