import { autoAssetsConfig } from "./autoAssetsConfig";
import { gameEventBus, AllGameEvents } from "./services";

/**
 * Собираем тут соотношения ассетов и звуков в игре!
 **/
export const soundConfig = {
  move: {
    soundNames: [
      autoAssetsConfig.sounds.broomSweep01.name,
      autoAssetsConfig.sounds.broomSweep02.name,
    ],
    volume: 0.45,
  },
  mergeByTileValue: {
    2: { soundNames: [autoAssetsConfig.sounds.pop1.name], volume: 0.55 },
    4: { soundNames: [autoAssetsConfig.sounds.pop1.name], volume: 0.55 },
    8: { soundNames: [autoAssetsConfig.sounds.pop2.name], volume: 0.58 },
    16: { soundNames: [autoAssetsConfig.sounds.pop2.name], volume: 0.58 },
    32: { soundNames: [autoAssetsConfig.sounds.pop3.name], volume: 0.62 },
    64: { soundNames: [autoAssetsConfig.sounds.pop3.name], volume: 0.62 },
    128: { soundNames: [autoAssetsConfig.sounds.pop3.name], volume: 0.62 },
    256: { soundNames: [autoAssetsConfig.sounds.pop4.name], volume: 0.66 },
    512: { soundNames: [autoAssetsConfig.sounds.pop4.name], volume: 0.66 },
    1024: { soundNames: [autoAssetsConfig.sounds.pop5.name], volume: 0.72 },
  },
};

export type SoundForEvents = Partial<{
  [EventName in keyof AllGameEvents]: (
    scene: Phaser.Scene,
    eventData: AllGameEvents[EventName],
  ) => void;
}>;

/** Реакции на события в игре - звуки подключаем тут, декларативно и четко **/
const soundForEvents: SoundForEvents = {
  onButtonClick: (scene) => scene.sound.play("click"),
  onButtonHover: (scene) => scene.sound.play("hoverCardFlip"),
  game2048Hammer: (scene) => scene.sound.play("glassHit"),
  tilesMove: (scene) => {
    const { soundNames, volume } = soundConfig.move;
    scene.sound.play(Phaser.Utils.Array.GetRandom(soundNames), { volume });
  },
  /** Выбирает pop-звук по исходному значению слившихся плиток. */
  game2048MergeParticles: (scene, { value }) => {
    const tileValue = value / 2;
    const soundEffect = Object.entries(soundConfig.mergeByTileValue)
      .filter(([value]) => Number(value) <= tileValue)
      .sort(([left], [right]) => Number(right) - Number(left))[0]?.[1];

    if (soundEffect) {
      const { soundNames, volume } = soundEffect;
      scene.sound.play(Phaser.Utils.Array.GetRandom(soundNames), { volume });
    }
  },
};

export const musicConfig = {
  soundName: "music",
  volume: 0.09,
};

type SoundEventHandler = (scene: Phaser.Scene, eventData?: unknown) => void;

export function listenSoundEvents(scene: Phaser.Scene): void {
  /** подписка на чисто игровые события**/
  Object.entries(soundForEvents).forEach(([eventName, callback]) => {
    if (!callback) return;

    const handler = callback as SoundEventHandler;

    gameEventBus.on(eventName as keyof AllGameEvents, (eventData?: unknown) => {
      handler(scene, eventData);
    });
  });
}

export function addButtonSounds(obj: Phaser.GameObjects.GameObject) {
  const emit = (event: keyof SoundForEvents) => gameEventBus.emit(event);
  obj.on(Phaser.Input.Events.GAMEOBJECT_POINTER_DOWN, () => emit('onButtonClick'));
  obj.on(Phaser.Input.Events.GAMEOBJECT_POINTER_OVER, () => emit('onButtonHover'));
}
