import { TypedEventsEmitter } from "../../events";
import { SingleSoundPlayer } from "../../sound/SingleSoundPlayer";

export interface ISoundSettings {
  isMusicOn: boolean;
  isSoundOn: boolean; // все звуки
}

interface ISoundFeatureEvents {
  /**
   * Usage:
   * - `auto_tuned/view-settings.ts` эмитит событие после изменения настроек.
   * - `shared/SoundPlayerFeature/SoundPlayerFeature.ts` слушает событие и применяет музыку/звук.
   * - Связанный кусок логики средний: настройка уже сохраняется во view, событие синхронизирует звуковую систему.
   */
  gameSettingsUpdated: ISoundSettings;

  /**
   * Команда владельцу звука пересчитать временный mute.
   *
   * Usage:
   * - `SpiderGameScene/ads/SpiderAdOverlayManager.ts` эмитит owner `ad` на время рекламы.
   * - `common/scenes/SceneLifeCycle/SceneLifeCycle.ts` эмитит совместимое событие owner `lifecycle` на platform pause/resume.
   * - `shared/SoundPlayerFeature/SoundPlayerFeature.ts` слушает совместимое событие и единолично применяет итоговый mute.
   * - Связанный кусок логики средний: несколько владельцев временного mute не должны размьючивать звук друг за другом.
   */
  soundMuteRequest: { owner: string; muted: boolean };
}

interface IProps {
  scene: Phaser.Scene;
  events: TypedEventsEmitter<ISoundFeatureEvents>;
  getSettings: () => ISoundSettings;
  musicConfig: {
    soundName: string;
    volume?: number;
  };
}

interface ISoundMuteRequest {
  owner: string;
  muted: boolean;
}

/**
 *  SoundPlayerFeature - "реализатор настроек звука"
 *. - подключи его в каждой сцене, чем раньше тем лучше
 *  - восстанавливает звуковое состояние игры при старте сцены
 *  - по scene.events, совместимым с  ISoundFeatureEvents,
 *      - гасит и восстанавливает звуки и музыку
 *      - применяет настройки к звукам и музыке
 *
 *  Не меняет, не сохраняет настройки сам!
 *  Это просто "реализатор настроек звука"
 *
 *  Потребность возникла в нем потому что кто-то должен
 *  - читать настройки в начале игры
 *  - слушать изменения настроек звуков и музыки
 *  - слушать запросы на гашение и воспроизведение музыки
 **/
export class SoundPlayerFeature {
  private readonly unSubs: Array<() => void> = [];
  private readonly activeMuteOwners = new Set<string>();

  private musicPlayer: SingleSoundPlayer;

  constructor(private readonly props: IProps) {
    const { scene, musicConfig, events } = props;
    this.musicPlayer = new SingleSoundPlayer({
      scene,
      ...musicConfig,
    });
    this.applySoundState();

    this.unSubs.push(
      events.on("gameSettingsUpdated", (settings) => {
        this.applySoundState(settings);
      }),
      events.on("soundMuteRequest", (data) => this.applyMuteRequest(data)),
    );
  }

  /** Применяет запрос временного mute от владельца вроде рекламы или lifecycle. */
  private applyMuteRequest(data: ISoundMuteRequest): void {
    if (data.muted) {
      this.activeMuteOwners.add(data.owner);
    } else {
      this.activeMuteOwners.delete(data.owner);
    }
    this.applySoundState();
  }

  /** Единственное место, где решается итоговое состояние музыки и mute сцены. */
  private applySoundState(settings: ISoundSettings = this.props.getSettings()): void {
    if (settings.isMusicOn) {
      this.musicPlayer.play();
    } else {
      this.musicPlayer.stop();
    }

    const muted = !settings.isSoundOn || this.activeMuteOwners.size > 0;
    this.props.scene.sound.mute = muted;
  }

  destroy(): void {
    this.unSubs.forEach((unSub) => unSub());
    this.unSubs.length = 0;
  }
}
