export function iosResumePatch(phaserGame: Phaser.Game) {

    const iOS = (navigator.userAgent.match(/(iPad|iPhone|iPod)/i) ? true : false);
    if (!iOS) return;

    phaserGame.events.on(
        Phaser.Core.Events.VISIBLE, // you can use .FOCUS here as well but then the sound only comes back after user interaction
        () => {
            setTimeout(() => {
                try {
                    const gameSound = phaserGame.sound as Phaser.Sound.WebAudioSoundManager || Phaser.Sound.HTML5AudioSoundManager;
                    gameSound.context.suspend();
                    gameSound.context.resume();
                } catch (e) {
                    console.warn(e)
                }
            }, 100);
        },
    );
}
