import { FireworksEffect, TypedEventsEmitter } from "../../../../common";
import { cinderella2048FireworksConfig } from "../../../../config.fireworks";
import type { IFireworksLayerEvents } from "./events";

interface IFireworksLayerProps {
  scene: Phaser.Scene;
  events: TypedEventsEmitter<IFireworksLayerEvents>;
}

/**
 * Отдельный декоративный слой игрового салюта основной scene.
 * Он слушает общий `game2048MergeParticles`, самостоятельно проверяет конфиг
 * и не добавляет в игровую модель знания о салюте или его правилах.
 **/
export class FireworksLayer {
  private readonly fireworks: FireworksEffect;

  /**
   * Создает собственный эффект основной scene и подписывает его на факты слияния плиток.
   * `game2048ClearParticles` синхронно очищает декорации при откате игрового хода.
   **/
  constructor({ scene, events }: IFireworksLayerProps) {
    const { assets, short } = cinderella2048FireworksConfig;
    this.fireworks = new FireworksEffect({
      scene,
      ...assets,
      emitterYRatio: short.emitterYRatio,
      particleOptions: short.particleOptions,
    });

    events.on("game2048MergeParticles", ({ value }) => {
      if (value >= short.minTileValue) {
        this.start();
      }
    });
    events.on("game2048ClearParticles", () => this.clear());
  }

  /** Уничтожает оба emitter и отложенный таймер короткого салюта. */
  destroy(): void {
    this.fireworks.destroy();
  }

  /** Запускает короткий салют после сборки плитки выше победной. */
  private start(): void {
    this.fireworks.startFor(cinderella2048FireworksConfig.short.durationMs);
  }

  /** Немедленно останавливает эмиссию и убирает оставшиеся частицы. */
  private clear(): void {
    this.fireworks.stop();
    this.fireworks.leftEmitter.killAll();
    this.fireworks.rightEmitter.killAll();
  }
}
