import { makeAlign } from "@kvisaz/phaser-sugar";
import { AdsService } from "../../services/ads";
import { ICommonAdEvents, IRewardAdData } from "./events";
import { TypedEventsEmitter } from "../../events";
import { InputBlocker } from "../../ui";

interface IAdOverlayManagerProps {
  scene: Phaser.Scene;
  adService: AdsService;
  events: TypedEventsEmitter<ICommonAdEvents>;
}

/** Управляет единым flow обычной и rewarded-рекламы на уровне игровой сцены. */
export class AdsOverlayManager {
  private readonly unSubs: Array<() => void> = [];
  private inputBlocker: InputBlocker | undefined;

  /** если блок инпута включен - уже работаем! **/
  private get busy() {
    return this.inputBlocker != null;
  }

  /** Подписывает manager на рекламные request-события сцены. */
  constructor(private readonly props: IAdOverlayManagerProps) {
    const { events } = props;

    this.unSubs.push(() => {
      this.inputBlocker?.destroy();
      this.inputBlocker = undefined;
    });
    this.unSubs.push(events.on("requestCommonAd", () => this.showCommonAd()));
    this.unSubs.push(events.on("requestRewardAd", (request) => this.showRewardAd(request)));
  }

  /** Снимает подписки manager-а. */
  destroy(): void {
    this.unSubs.forEach((unSub) => unSub());
    this.unSubs.length = 0;
  }

  /** Запускает fullscreen-рекламу и всегда возвращает результат через событие. */
  private showCommonAd(): void {
    const { events, adService } = this.props;

    if (this.busy) {
      events.emit("onCommonAdClosed", { wasShown: false, error: "ad flow is busy" });
      return;
    }

    this.startAdFlow();
    adService.showCommonAd((result) => {
      this.finishAdFlow();
      events.emit("onCommonAdClosed", result);
    });
  }

  private showRewardAd(request: IRewardAdData): void {
    const { events, adService } = this.props;

    if (this.busy) {
      events.emit("onRewardAdClosed", {
        rewardType: request.rewardType,
        wasShown: false,
        error: "ads busy",
      });
      return;
    }

    this.startAdFlow();
    adService.showRewardedAd((result) => {
      this.finishAdFlow();
      events.emit("onRewardAdClosed", {
        rewardType: request.rewardType,
        wasShown: result.wasShown,
        error: result.error,
      });
    });
  }

  /** Начинает рекламный flow: блокирует ввод, ставит busy и останавливает звук. */
  private startAdFlow(): void {
    this.blockInput(true);
    this.props.events.emit("soundMuteRequest", { owner: "ads", muted: true });
  }

  /** Завершает рекламный flow: снимает блокировку ввода, возвращает звук и сбрасывает busy. */
  private finishAdFlow(): void {
    this.blockInput(false);
    this.props.events.emit("soundMuteRequest", { owner: "ads", muted: false });
  }

  /** Создает или снимает прозрачный перехватчик ввода поверх HUD без изменения состояния кнопок. */
  private blockInput(blocked: boolean) {
    this.inputBlocker?.destroy();
    this.inputBlocker = undefined;

    if (blocked) {
      const { scene } = this.props;
      const inputBlocker = new InputBlocker({ scene });
      makeAlign((align) => {
        align.anchorSceneScreen(scene).center(inputBlocker);
      });
      scene.add.existing(inputBlocker);
      this.inputBlocker = inputBlocker;
    }
  }
}
