import { onGameObjectDataKeyChange } from "../../gameObjects";

const VALUE_DATA_KEY = "value";

/**
 * установить данные в переменную value
 * - годится для view которые слушают изменение этого значения
 * **/
export function setValueData<T>(obj: Phaser.GameObjects.GameObject, value: T) {
  obj.setData(VALUE_DATA_KEY, value);
}

/**
 * Слушать изменения value
 ***/
export function onValueData<T>(obj: Phaser.GameObjects.GameObject, onChange: (value: T) => void) {
  return onGameObjectDataKeyChange<T>({
    obj,
    dataKey: VALUE_DATA_KEY,
    callback: onChange,
  });
}
