import type { SubscribeOnly } from "../../../common";
import { vpx } from "../../../common";
import { hammerInfoCardConfig } from "./constants";
import type { IHammerInfoEvents } from "./events";
import { HammerInfoCardView } from "./HammerInfoCardView";

export interface IHammerInfoCardProps {
  scene: Phaser.Scene;
  events?: SubscribeOnly<IHammerInfoEvents>;
  onRemoveClick: () => void;
}

/** Управляет показом, скрытием и внешней реакцией карточки молотка. */
export class HammerInfoCard {
  private readonly view: HammerInfoCardView;
  private readonly unSubs: Array<() => void> = [];
  private isShown = false;

  /** Создает скрытую карточку и при наличии events следит за режимом курсора. */
  constructor(private readonly props: IHammerInfoCardProps) {
    const { scene, events } = props;
    this.view = new HammerInfoCardView({
      scene,
      onRemoveClick: this.handleRemoveClick,
    });
    this.placeOutsideScreen();
    this.view.setVisible(false);

    if (events != null) {
      this.unSubs.push(
        events.on("setCursor", ({ type }) => {
          if (type === "hammer") {
            this.show();
          } else {
            this.hide();
          }
        }),
      );
    }
  }

  /** Уничтожает карточку, активную анимацию и подписки на события. */
  destroy(): void {
    this.unSubs.forEach((unSub) => unSub());
    this.props.scene.tweens.killTweensOf(this.view);
    this.view.destroy();
  }

  /** Плавно выдвигает карточку справа и оставляет заданный отступ от края. */
  show(): void {
    if (this.isShown) return;

    const { scene } = this.props;
    const { animation } = hammerInfoCardConfig;
    const targetPosition = this.getVisiblePosition();

    this.isShown = true;
    scene.tweens.killTweensOf(this.view);
    if (!this.view.visible) {
      this.placeOutsideScreen();
    }
    this.view.setVisible(true);
    this.view.y = targetPosition.y;
    scene.tweens.add({
      targets: this.view,
      x: targetPosition.x,
      duration: animation.showDurationMs,
      ease: animation.showEase,
    });
  }

  /** Плавно убирает карточку за правую границу экрана. */
  hide(): void {
    if (!this.isShown) return;

    const { scene } = this.props;
    const { animation } = hammerInfoCardConfig;

    this.isShown = false;
    scene.tweens.killTweensOf(this.view);
    scene.tweens.add({
      targets: this.view,
      x: this.getHiddenX(),
      duration: animation.hideDurationMs,
      ease: animation.hideEase,
      onComplete: () => {
        if (!this.isShown) {
          this.view.setVisible(false);
        }
      },
    });
  }

  /** Передает клик владельцу карточки и сразу запускает ее скрытие. */
  private readonly handleRemoveClick = (): void => {
    this.props.onRemoveClick();
    this.hide();
  };

  /** Ставит карточку целиком за правую границу экрана. */
  private placeOutsideScreen(): void {
    const { y } = this.getVisiblePosition();
    this.view.setPosition(this.getHiddenX(), y);
  }

  /** Рассчитывает центр карточки с учетом отступа от правого края. */
  private getVisiblePosition(): { x: number; y: number } {
    const { scene } = this.props;
    const { width } = this.view.getBounds();

    return {
      x: scene.scale.width - vpx(hammerInfoCardConfig.rightOffset) - width / 2,
      y: scene.scale.height * hammerInfoCardConfig.verticalPositionRatio,
    };
  }

  /** Рассчитывает позицию, в которой карточка полностью скрыта справа. */
  private getHiddenX(): number {
    const { scene } = this.props;
    const { width } = this.view.getBounds();

    return scene.scale.width + width / 2 + vpx(hammerInfoCardConfig.hiddenOffset);
  }
}
