/**
 * Здесь можно складывать утилиты для сборки конкретных реализаций
 * разных вещей для игры
 **/

import { PreloadTask } from "@kvisaz/phaser-sugar";
import { getLocaleFromUrl, getLocalizedText, setLocaleFromExternal } from "./view-elements/locale";
import { preloadServices, yandexSdkWrapper } from "./services";
import { preloadAllAssets } from "./scenes/shared";
import { backgroundConfig } from "./config.backgrounds";
import { setVpx } from "./common";

/* ---------------------------------------------------------
 *  preload для Boot
 * --------------------------------------------------------- */
export function preloadBoot(scene: Phaser.Scene) {

  setVpx(scene.scale.width);

  /**
   * ассеты не зависят от сервисов и грузятся параллельно
   **/
  preloadAllAssets({
    scene,
    backgroundStages: backgroundConfig.stages,
  });

  /**
   * preload task - делает параллельную загрузку
   * поэтому для сервисов, зависящих от yandexSdkWrapper
   * надо делать единую функцию
   * **/
  PreloadTask.load(scene, preloadServices());
}

/* ---------------------------------------------------------
 *  Включаем локализованный title
 * --------------------------------------------------------- */
export function setupLocalizedTitle() {
  document.title = getLocalizedText("gameName");
}

/* ---------------------------------------------------------
 *  Отключаем контекстное меню браузера - требования Y
 * --------------------------------------------------------- */
export function removeContextMenu() {
  document.body.addEventListener("contextmenu", (e) => e.preventDefault());
}

/**
 * Локализация - допустимо ставить в BootScene перед запуском
 * - yandex SDK если есть
 * - из url
 **/
export function setupGameLocale() {
  setLocaleFromExternal([() => yandexSdkWrapper.getLanguage(), getLocaleFromUrl]);
  setupLocalizedTitle(); // прямую модификацию title сразу делаем тут
}
