/**
 * универсальная оболочка для всех дата-сервисов
 * с внутренним кэшем
 * **/
export interface InstantDataService {
  /** загрузка в кэш из реализации **/
  preload(): Promise<void>;

  /**
   * моментальное сохранение в кэш,
   * ожидание результата сохранения в реализацию
   * **/
  setData<T>(key: string, value: T, saveImmediately?: boolean): Promise<SaveResult>;

  /**
   * моментальное чтение из кэша
   * **/
  getData<T>(key: string): T | undefined;
}

export interface SaveResult {
  errorMessage?: string;
  timeToNextSave?: number;
  skipReason?: string
}

export const SuccessSaveResult: SaveResult = {} as const;
export const isFailSave = (result: SaveResult)=>result.errorMessage!=null;
