import { AutoAssetImage, getAtlasImgAsset, getFontFamilyAsset } from "../../autoAssetHelpers";
import { makeButton, row, safeArray, vpx } from "../../common";
import { makeView } from "../../common/gameObjects/makeView/makeView";
import { makeAlign } from "@kvisaz/phaser-sugar";
import { addButtonSounds } from "../../config.sound";

export interface ICindTextButtonProps {
  scene: Phaser.Scene;
  type: ButtonType;
  text: string;
  rewardIcon?: boolean;
  onClick: (obj: Phaser.GameObjects.GameObject) => void;
}

type ButtonType = "primary" | "secondary";
const assetsMap: Record<ButtonType, AutoAssetImage> = {
  primary: "buttonPrimaryNine20",
  secondary: "buttonSecondaryNine20",
};

/**
 *  Текстовая кнопка

 *  -- текст
 *  -- onClick
 *  -- эффект hover без gl
 *  -- эффект нажатия?
 *  -   размеры в vpx
 *  -   enable/disable
 *
 *   излучает
 *   onClick: 'onButtonClick',
 *   onHover: 'onButtonHover',
 *   onOut: 'onButtonOut',
 **/
export function createCindTextButton({ scene, text, onClick, type, rewardIcon }: ICindTextButtonProps) {
  const iconAsset = getAtlasImgAsset("iconPlayFull44");
  const nineAsset = getAtlasImgAsset(assetsMap[type]);

  const textStyle: Phaser.Types.GameObjects.Text.TextStyle = {
    fontFamily: getFontFamilyAsset("interSemibold"),
    fontSize: `${vpx(36)}px`,
    fontStyle: "bold",
    color: type === 'primary' ? '#ffffff' : '#207725'
  };
  const button = makeView(scene, (b) => {
    const bg = b.nine({
      ...nineAsset,
      width: vpx(320),
      height: vpx(60),
      padding: vpx(20),
    });

    const textView = b.text({ text, style: textStyle });

    const icon = rewardIcon ? b.img(iconAsset) : undefined;

    makeAlign((align) => {
      const content = icon != null ? row([textView, icon], { nextOffsetX: vpx(10) }) : textView;
      align.anchor(bg).center(content);
    });

    return b.con(safeArray([bg, textView, icon]));
  });

  makeButton({
    obj: button,
    onClick,
    onEnabledChange: (obj, enabled) => {
      obj.setAlpha(enabled ? 1 : 0.45);
    },
  });
  // привязка локальных звуков
  addButtonSounds(button);

  button.name = `button-text-${type}`;
  return button;
}
