import { getErrorMessage } from "../../string";
import { InstantDataService, SaveResult, SuccessSaveResult } from "./types";

interface IProps {
  appId: string;
}

export class LocalDataService implements InstantDataService {
  private cache: Record<string, unknown | undefined>;

  get storageKey() {
    return `${this.props.appId}-local`;
  }

  constructor(private props: IProps) {
    this.cache = {};
  }

  async preload(): Promise<void> {
    try {
      this.loadCache();
    } catch (e) {
      console.warn(e);
    }
  }

  getData<T>(key: string): T | undefined {
    return this.cache[key] as T | undefined;
  }

  async setData<T>(key: string, value: T): Promise<SaveResult> {
    this.cache[key] = value;
    try {
      return this.saveCache();
    } catch (e) {
      console.warn(e);
      return { errorMessage: getErrorMessage(e) };
    }
  }

  /** Записывает текущий кэш в localStorage и возвращает результат фактической записи. */
  private saveCache(): SaveResult {
    if (!hasLocalStorage()) {
      return { errorMessage: "localStorage недоступен" };
    }
    localStorage.setItem(this.storageKey, JSON.stringify(this.cache));
    return SuccessSaveResult;
  }

  private loadCache() {
    if (!hasLocalStorage()) {
      console.warn("no storage");
      return;
    }

    const saved = localStorage.getItem(this.storageKey);
    if (!saved) return;

    const parsed: unknown = JSON.parse(saved);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      this.cache = parsed as Record<string, unknown>;
    }
  }
}

function hasLocalStorage(): boolean {
  return typeof window !== "undefined" && typeof window?.localStorage !== "undefined";
}
