export enum MoveDirection {
  up='up',
  down='down',
  right='right',
  left='left'
}

export type TileSpawnReason = "initial" | "move";

export interface IGameCore2048Config {
  /** Этап, с которого начинается партия. */
  startStageValue: number;

  /** Максимальная плитка, доступная в текущем сценарии игры. */
  maxTileValue: number;

  /** Значение плитки, при котором показывается победный диалог. */
  winValue: number;
}

export interface IGame2048HammerConfig {
  /** Безусловно включает или выключает фичу молотка. */
  hammerFeature: boolean;

  /** Максимальное количество молотков, которое может быть у игрока. */
  hammerMax: number;

  /** Минимальная собранная плитка, с которой возможна выдача молотка. */
  hammerTileMin: number;

  /** Вероятность выдачи одного молотка за подходящую собранную плитку. */
  hammerTileProbability: number;

  /** Стартовое количество молотков для новой партии. */
  hammerStartAmount: number;

  /** Количество молотков за рекламную награду. */
  hammerRewardAmount: number;

  /** Минимальное количество плиток на поле, при котором молоток можно применить. */
  hammerBoardFillAmountMin: number;
}

export interface IGame2048UndoConfig {
  /** Безусловно включает или выключает расходуемый undo. */
  undoFeature: boolean;

  /** Максимальное количество undo; 0 означает отсутствие ограничения. */
  undoMax: number;

  /** Стартовое количество undo для новой партии. */
  undoStartAmount: number;

  /** Количество undo за рекламную награду. */
  undoRewardAmount: number;
}

export type Game2048Config = IGameCore2048Config & IGame2048HammerConfig & IGame2048UndoConfig;

export interface ITileSpawnPolicy {
  /** Возвращает значение новой плитки для указанного типа спавна. */
  getTileValue(reason: TileSpawnReason): number;
}

export interface ITileMergePolicy {
  /** Проверяет, разрешено ли слияние одинаковых плиток с учетом лимитов текущего сценария. */
  canMerge(leftValue: number, rightValue: number): boolean;
}

export interface IGame2048Cell {
  row: number;
  col: number;
}

export interface IGame2048MergeEvent extends IGame2048Cell {
  value: number;
}

export interface IGame2048TileMotion {
  tileId: number;
  toRow: number;
  toCol: number;
}

export interface IGame2048MoveResult {
  moved: boolean;
  scoreGained: number;
  mergeEvents: IGame2048MergeEvent[];
  tileMotions: IGame2048TileMotion[];
  mergeTargetIds: number[];
}

/** Чистая плитка для истории undo и сохранения партии. */
export interface IHistoryTile {
  id: number;
  value: number;
}

export type IHistoryRows = Array<Array<IHistoryTile | null>>;

/** Чистый снимок поля для истории undo и сохранения партии. */
export interface IHistorySnapshot {
  /** Матрица чистых плиток без runtime-анимаций. */
  grid: IHistoryRows;

  /** Счет на момент снимка. */
  score: number;

  /** Количество успешных ходов на момент снимка. */
  moves: number;

  /** Факт достижения победной плитки на доске; не означает открытый экран победы. */
  won: boolean;
}

/** легкая сохраненка */
export interface ISaveData {
  bestScore: number;
  boardSnapshot?: IHistorySnapshot;
  history?: IHistorySnapshot[];
  maxReachedTile: number;
  hammerAmount: number;
  undoAmount: number;
}
