import { Player } from "ysdk";
import { getErrorMessage } from "../../string";
import { InstantDataService, SaveResult } from "./types";
import { areEquals } from "../../mapAndObjects";
import { MinimalTimeIntervalStrategy } from "../utils/MinimalTimeIntervalStrategy";
import { SaveCacheStrategy } from "./SaveCacheStrategy";

const SECOND = 1000;
const minimalDataSaveInterval = 5 * SECOND;

/**
 * Сохраняет в памяти всегда новое значение
 * Пытается! сохранить в облаке
 * Возвращает сообщение об ошибке если в облаке сохранить не удалось
 *
 *  Не переписывать класс!
 *  - допустимый компромисс простоты и хрупкости
 *  - усложнение приведет к более опасным и мучительным багам
 *  - если надо жестко сохранить - управляй через saveService пока не получится сохранить
 *  -
 *
 **/
export class YandexDataService implements InstantDataService {
  /**
   * Это живой кэш в памяти для хранения данных
   * он может быть не полностью синхронизирован с данными
   *
   *   асинхронщина - то есть ожидание сейва - приведет к тому
   *   что кто-то прочитает данные которые уже должны обновиться но висят ждут сейва
   *   и этот код будет гораздо более страшным в багах
   *  **/
  private cache: Record<string, unknown | undefined>;

  private timeLogic: MinimalTimeIntervalStrategy = new MinimalTimeIntervalStrategy(
    minimalDataSaveInterval,
  );

  private cloudSaveLogic: SaveCacheStrategy = new SaveCacheStrategy();

  constructor(private player: Player) {
    this.cache = {};
  }

  async preload(): Promise<void> {
    try {
      const data: unknown = await this.player.getData();
      if (data && typeof data === "object" && !Array.isArray(data)) {
        this.cache = data as Record<string, unknown>;
      }
    } catch (error) {
      console.warn(error);
    }
  }

  /**
   * сохранять можно данные любого пользователя, и авторизованного, и неавторизованного,
   поскольку у любого пользователя есть uniqueID с накопленным прогрессом
   если пользователь не авторизован, его uniqueID хранится локально.
   Поэтому uniqueID может измениться,
   если пользователь зайдет с другого браузера или устройства, либо удалиться,
   если пользователь очистит кэш браузера.
   **/
  getData<T>(key: string): T | undefined {
    return this.cache[key] as T | undefined;
  }

  /**
   *  Установка данных в кэш
   *  - только если есть изменения
   *  - только если допустим интервал записей
   *  - возвращает время до следующей допустимой записи
   *  !  для любой практически игры - приемлемо потерять последние 1-5 секунд
   *     прогресса при резком закрытии вкладки
   ***/
  async setData<T>(key: string, value: T, saveImmediately?: boolean): Promise<SaveResult> {
    try {
      const prevValue = this.cache[key];
      if (areEquals(value, prevValue) && this.cloudSaveLogic.isAlreadySaved(key, value)) {
        return this.getSkippedResult("no save needed: values are equals");
      }
      /** обновляем кэш моментально **/
      this.cache[key] = value;

      /** попытка сейва **/
      if (!this.timeLogic.isAllowed()) {
        return this.getErrorResult("no minimal time interval");
      }
      this.timeLogic.markTime();
      await this.player.setData({ [key]: value } as Record<string, unknown>, saveImmediately);
      this.cloudSaveLogic.markSaved(key, value);
      return this.getSuccessResult();
    } catch (error) {
      return this.getErrorResult(error);
    }
  }

  private getErrorResult(error: unknown): SaveResult {
    return {
      errorMessage: getErrorMessage(error),
      ...this.getTimePerResult(),
    };
  }

  private getSuccessResult(): SaveResult {
    return {
      ...this.getTimePerResult(),
    };
  }

  private getSkippedResult(skipReason: string): SaveResult {
    return {
      ...this.getTimePerResult(),
      skipReason,
    };
  }

  private getTimePerResult(): SaveResult {
    return {
      timeToNextSave: this.timeLogic.getTimeToNextSave(),
    };
  }
}
