import { getPowersOfTwo, getUrlParam, isAllowedHost, isPowerOfTwo } from "./common";
import { getLocalizedText } from "./view-elements/locale";

interface IProps {
  isAllowed?: boolean;
}

const allowedHosts = ["localhost", "kvisaz.github.io"];

class CheatCodeService {
  private get isAllowed() {
    return this.props.isAllowed ?? isAllowedHost(allowedHosts);
  }

  constructor(private props: IProps) {}

  /** Возвращает стартовый уровень 2048 из URL-параметра min. */
  getStartLevel2048(): number | undefined {
    const cheatUrlParamName = "min";
    if (!this.isAllowed) return;
    const level = getUrlParam(cheatUrlParamName);

    if (level == null) {
      return;
    }

    const parsedLevel = Number(level);

    if (!Number.isFinite(parsedLevel)) {
      return;
    }

    const min = 2;
    const max = 131072;
    if (!isPowerOfTwo(parsedLevel, { min, max})) {
      window.alert([
        getLocalizedText("cheatInvalidMinCode", { level }),
        getLocalizedText("cheatUsePowerOfTwo", { values: getPowersOfTwo(min, max).join(", ") }),
        getLocalizedText("cheatExampleMin", { example: 128 }),
      ].join("\n"));
      return;
    }

    return parsedLevel;
  }
}



export const cheatCode = new CheatCodeService({});
