interface ISingleSoundPlayer {
    scene: Phaser.Scene;
    soundName: string;
    volume?: number;
}

/** Плеер для 1 звука чтобы найти его, остановить или продолжить **/
export class SingleSoundPlayer {
    constructor(private props: ISingleSoundPlayer) {
    }

    stop() {
        const {soundName, volume, scene} = this.props;
        scene.sound.get(soundName)?.stop();
    }

    play() {
        const {soundName, volume, scene} = this.props;
        /** Паттерн для переиспользования звука - иначе мы не сможем ее останавливатья **/
        const sound = scene.sound.get(soundName) ?? scene.sound.add(soundName);
        if (sound.isPlaying) {
            return;
        }
        if (sound.isPaused) {
            sound.resume();
            return;
        }

        sound.play({volume, loop: true});
    }
}
