declare const __PUBLISH_BUILD__: boolean | undefined;

/** Константы, которые Vite подставляет на этапе сборки. */
export const buildConstants = {
    /** typeof не падает вне Vite-сборки, где __PUBLISH_BUILD__ может не существовать в runtime. */
    publishBuild: typeof __PUBLISH_BUILD__ !== "undefined" ? __PUBLISH_BUILD__ : false,
};
