import { Player, SDK } from "ysdk";

interface IProps {
  isLogging?: boolean;
}

export class YandexSdkWrapperV2 {
  protected sdk: SDK | undefined;
  protected player: Player | undefined;

  private flags: { isReadySent?: boolean } = { };

  constructor(private props: IProps = {}) {}

  async init() {
    try {
      if (typeof YaGames === "undefined" || YaGames == null) {
        this.log("YaGames unavailable");
        return;
      }
      if (this.sdk == null) {
        this.sdk = await YaGames.init();
      }
      if (this.player == null) {
        this.player = await this.sdk?.getPlayer();
      }
    } catch (e) {
      this.log(e);
    }
  }

  getSDK(): SDK | undefined {
    return this.sdk;
  }

  getPlayer(): Player | undefined {
    return this.player;
  }

  getLanguage(): string | undefined {
    return this.sdk?.environment.i18n.lang;
  }

  /**
   * Сообщает платформе Yandex Games, что игра загрузилась и готова к взаимодействию.
   */
  signalGameReady(): void {
    try {
      if(this.flags.isReadySent) return;
      const api = this.sdk?.features?.LoadingAPI;
      if(api){
        api.ready();
        this.flags.isReadySent = true;
      }
    } catch (e) {
      this.log(e);
    }
  }

  /**
   * Сообщает платформе Yandex Games, что игрок начал или возобновил игровой процесс.
   * запуск уровня;
   * закрытие меню;
   * снятие с паузы;
   * возобновление игры после показа рекламы;
   * возвращение в текущую вкладку браузера.
   */
  signalGameplayStart(): void {
    try {
      this.sdk?.features?.GameplayAPI?.start();
    } catch (e) {
      this.log(e);
    }
  }

  /**
   * Сообщает платформе Yandex Games, что игрок остановил игровой процесс.
   * прохождение уровня или проигрыш;
   * вызов меню;
   * пауза в игре;
   * показ полноэкранной или rewarded-рекламы;
   * уход в другую вкладку браузера.
   */
  signalGameplayStop(): void {
    try {
      this.sdk?.features?.GameplayAPI?.stop();
    } catch (e) {
      this.log(e);
    }
  }


  protected log(...args: unknown[]) {
    if (this.props.isLogging !== true) return;
    console.log(...args);
  }
}
