import { getCanvasSize } from "../size";
import { cssColorToInt } from "@kvisaz/phaser-sugar";

interface InputBlockerProps {
  scene: Phaser.Scene;
}

/** Прозрачный интерактивный прямоугольник, который перехватывает ввод поверх UI. */
export class InputBlocker extends Phaser.GameObjects.Rectangle {
  constructor(private props: InputBlockerProps) {
    const { width, height } = getCanvasSize(props.scene);
    super(props.scene, 0, 0, width, height, cssColorToInt("#dedede"), 0);
    this.setInteractive();
  }
}
