import { HtmlCrossfadeBackground } from "../../../../common/html";
import { TypedEventsEmitter } from "../../../../common";
import { onSceneShutdown } from "../../../../common/scenes";
import type { ICinderella2048BackgroundStage } from "./types";
import type { ICinderella2048BackgroundManagerEvents } from "./events";

interface ICinderella2048BackgroundManagerProps {
  scene: Phaser.Scene;
  events: TypedEventsEmitter<ICinderella2048BackgroundManagerEvents>;
  backgroundStages: ICinderella2048BackgroundStage[];
  transitionDurationMs?: number;
}

/** Управляет HTML-фоном сцены Cinderella 2048 по образцу BgAssetManager из Паука. */
export class Cinderella2048BackgroundManager {
  private bg?: HtmlCrossfadeBackground;
  private disposeSceneShutdown: () => void;
  private currentStage?: ICinderella2048BackgroundStage;

  private get gameEvents() {
    return this.props.events;
  }

  /** Создает manager и сразу применяет стартовый фон сцены. */
  constructor(private readonly props: ICinderella2048BackgroundManagerProps) {
    const initialStage = this.getStageForMaxTile(0);

    this.disposeSceneShutdown = onSceneShutdown(props.scene, () => this.destroy());
    this.currentStage = initialStage;
    this.bg = new HtmlCrossfadeBackground({
      url: initialStage.url,
      fallbackUrl: initialStage.fallbackUrl,
      defaultUrl: initialStage.url,
      durationMs: props.transitionDurationMs,
    });
    this.gameEvents.on("game2048MaxTileChange", ({ maxTile }) =>
      this.applyStageForMaxTile(maxTile),
    );
  }

  /** Выбирает фон для максимальной достигнутой плитки и запускает crossfade при смене этапа. */
  private applyStageForMaxTile(maxTile: number): void {
    const nextStage = this.getStageForMaxTile(maxTile);

    if (this.currentStage?.url === nextStage.url) {
      return;
    }

    this.currentStage = nextStage;
    this.bg?.setBackground({
      url: nextStage.url,
      fallbackUrl: nextStage.fallbackUrl,
      defaultUrl: this.getStageForMaxTile(0).url,
    });
  }

  /** Возвращает последний подходящий фон по порогу максимальной плитки. */
  private getStageForMaxTile(maxTile: number): ICinderella2048BackgroundStage {
    const sortedStages = [...this.props.backgroundStages].sort(
      (left, right) => left.minTile - right.minTile,
    );
    const firstStage = sortedStages[0];

    if (!firstStage) {
      throw new Error("Cinderella2048BackgroundManager: backgroundStages must not be empty");
    }

    let result = firstStage;

    for (const stage of sortedStages) {
      if (maxTile >= stage.minTile) {
        result = stage;
      }
    }

    return result;
  }

  /** Возвращает HTML-фон страницы в состояние до запуска сцены. */
  destroy(): void {
    this.disposeSceneShutdown();
    this.bg?.destroy();
    this.bg = undefined;
    this.currentStage = undefined;
  }
}
