import { isValidHistorySnapshot } from "./guards";
import type {
  IHistorySnapshot,
  IHistoryTile,
  ISaveData,
} from "./types";
import { getEmptySaveState } from "./emptySpaces";
import { IGame2048State } from "../types";

/** Проверяет, что значение является обычным объектом для нормализации сохранения. */
function isRecord(value: unknown): value is Record<string, unknown> {
  return value != null && typeof value === "object" && !Array.isArray(value);
}

/** Проверяет, что значение является конечным числом не меньше нуля. */
function isNonNegativeNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value) && value >= 0;
}

/** Создает чистую плитку истории из проверенных данных. */
function createCleanHistoryTile(tile: IHistoryTile): IHistoryTile {
  return {
    id: tile.id,
    value: tile.value,
  };
}

/** Создает чистый снимок истории из проверенных данных. */
function createCleanHistorySnapshot(snapshot: IHistorySnapshot): IHistorySnapshot {
  const historySnapshot: IHistorySnapshot = {
    grid: snapshot.grid.map((row) => row.map((tile) => tile ? createCleanHistoryTile(tile) : null)),
    score: snapshot.score,
    moves: snapshot.moves,
    won: snapshot.won,
  };

  return historySnapshot;
}

/** Нормализует загруженное сохранение до состояния, безопасного для запуска игры. */
export function normalizeSaveData(value: unknown): ISaveData {
  const saveData = getEmptySaveState();

  if (!isRecord(value)) {
    return saveData;
  }

  /** восстанавливаем вечные данные и имущество **/
  saveData.bestScore = isNonNegativeNumber(value.bestScore) ? value.bestScore : 0;
  saveData.hammerAmount = isNonNegativeNumber(value.hammerAmount) ? value.hammerAmount : 0;
  saveData.undoAmount = isNonNegativeNumber(value.undoAmount) ? value.undoAmount : 0;

  const boardSnapshot = isValidHistorySnapshot(value.boardSnapshot)
    ? createCleanHistorySnapshot(value.boardSnapshot)
    : undefined;
  if (boardSnapshot) {
    saveData.boardSnapshot = boardSnapshot;
  }

  /** История и прогресс партии имеют смысл только вместе с валидной текущей доской. */
  const history = boardSnapshot && Array.isArray(value.history)
    ? value.history.filter(isValidHistorySnapshot).map(createCleanHistorySnapshot)
    : undefined;
  if (history) {
    saveData.history = history;
  }
  /** Прогресс старой партии нельзя переносить на новую случайную доску. */
  if (boardSnapshot) {
    saveData.maxReachedTile = isNonNegativeNumber(value.maxReachedTile)
      ? value.maxReachedTile
      : 0;
  }

  return saveData
}


/** Нормализует загруженное сохранение до состояния, безопасного для запуска игры. */
export function mapGame2SaveData(gameState: IGame2048State): ISaveData {
  return {
    bestScore: gameState.bestScore,
    boardSnapshot: gameState.boardSnapshot,
    history: gameState.history,
    maxReachedTile: gameState.maxReachedTile,
    hammerAmount: gameState.hammerAmount,
    undoAmount: gameState.undoAmount,
  }
}
