import { game2048CoreConfig } from "../model";
import type { Game2048TileSpriteKey, IGame2048SpriteAsset, IGame2048SpriteConfig } from "../types";
import { tileAnimationConfig } from "./constants";

interface IGame2048TileViewProps {
  scene: Phaser.Scene;
  value: number;
  bounds: Phaser.Geom.Rectangle;
  spriteConfig: IGame2048SpriteConfig;
}

/** Отображает одну плитку 2048 и проигрывает ее локальные Phaser tweens. */
export class Game2048TileView extends Phaser.GameObjects.Image {
  private restingX = 0;
  private restingScale = 1;
  private cellWidth = 0;

  /** Создает картинку плитки из atlas-конфига. */
  constructor(private props: IGame2048TileViewProps) {
    const spriteAsset = getSpriteAsset(props.spriteConfig, props.value);

    super(props.scene, 0, 0, spriteAsset.textureName, spriteAsset.frameName);

    this.setOrigin(0.5);
    this.setTile(props.value, props.bounds);
  }

  /** Останавливает tweens плитки перед уничтожением Phaser-объекта. */
  destroy(fromScene?: boolean): void {
    this.stopAnimations();
    super.destroy(fromScene);
  }

  /** Останавливает активные tweens и возвращает устойчивые scale и X плитки. */
  stopAnimations(): void {
    this.scene.tweens.killTweensOf(this);
    this.setX(this.restingX);
    this.setScale(this.restingScale);
  }

  /** Устанавливает значение, геометрию и точное покоящееся состояние плитки. */
  setTile(value: number, bounds: Phaser.Geom.Rectangle): void {
    const spriteAsset = getSpriteAsset(this.props.spriteConfig, value);

    this.setTexture(spriteAsset.textureName, spriteAsset.frameName);
    this.restingX = bounds.centerX;
    this.cellWidth = bounds.width;
    this.restingScale = Math.min(bounds.width / this.width, bounds.height / this.height);
    this.setPosition(bounds.centerX, bounds.centerY);
    this.setScale(this.restingScale);
  }

  /** Проигрывает появление новой плитки через штатный Back.Out easing Phaser. */
  playSpawn(onComplete?: () => void): void {
    this.setScale(this.restingScale * tileAnimationConfig.spawnStartScale);
    this.scene.tweens.add({
      targets: this,
      scaleX: this.restingScale,
      scaleY: this.restingScale,
      duration: game2048CoreConfig.timings.spawnMs,
      ease: Phaser.Math.Easing.Back.Out,
      onComplete: () => {
        this.setScale(this.restingScale);
        onComplete?.();
      },
    });
  }

  /** Проигрывает pop слияния с прежней синусоидальной амплитудой. */
  playMerge(onComplete?: () => void): void {
    this.scene.tweens.add({
      targets: this,
      scaleX: this.restingScale * tileAnimationConfig.mergePeakScale,
      scaleY: this.restingScale * tileAnimationConfig.mergePeakScale,
      duration: game2048CoreConfig.timings.mergeMs / 2,
      ease: Phaser.Math.Easing.Sine.Out,
      yoyo: true,
      onComplete: () => {
        this.setScale(this.restingScale);
        onComplete?.();
      },
    });
  }

  /** Включает или выключает непрерывное дрожание плитки под молотком. */
  setHammerShake(active: boolean): void {
    this.stopAnimations();

    if (!active) {
      return;
    }

    const amplitude = this.cellWidth * tileAnimationConfig.hammerAmplitudeRatio;
    const duration = tileAnimationConfig.hammerQuarterDurationMs;

    this.scene.tweens.chain({
      targets: this,
      loop: -1,
      tweens: [
        { x: this.restingX + amplitude, duration, ease: Phaser.Math.Easing.Sine.Out },
        { x: this.restingX, duration, ease: Phaser.Math.Easing.Sine.In },
        { x: this.restingX - amplitude, duration, ease: Phaser.Math.Easing.Sine.Out },
        { x: this.restingX, duration, ease: Phaser.Math.Easing.Sine.In },
      ],
    });
  }
}

/** Возвращает atlas-asset плитки для игрового значения. */
function getSpriteAsset(spriteConfig: IGame2048SpriteConfig, value: number): IGame2048SpriteAsset {
  const key = `tile${value}` as Game2048TileSpriteKey;

  return spriteConfig[key];
}
