import { State } from "../../events";
import type { Observable, TypedEventsEmitter } from "../../events";
import type { SaveResult } from "../../services/DataService";
import {
  game2048CoreConfig,
  Game2048GridModel,
  createTileMergePolicy,
  createTileSpawnPolicy,
  isValidHistorySnapshot,
  mapGame2SaveData,
  MoveDirection,
} from "./model";
import type {
  Game2048TileModel,
  Game2048Config,
  IGame2048MergeEvent,
  IGame2048MoveResult,
  ISaveData,
} from "./model";
import type { IGame2048EffectPayload, IGame2048Events } from "./events";
import { Game2048BoardView } from "./components/Game2048BoardView";
import { Game2048InputController } from "./components/Game2048InputController";
import type {
  Game2048ToolMode,
  IGame2048SpriteConfig,
  IGame2048State,
} from "./types";
import {
  createContinueState,
  createHammerState,
  createInitState,
  createInputUnlockedState,
  createMoveState,
  createToolModeState,
  createUndoState,
} from "./reducer";
import type { IGame2048BoardViewConfig } from "./components/types";
import { getEmptySaveState } from "./model/emptySpaces";

export interface IGame2048Props {
  scene: Phaser.Scene;
  boardConfig: IGame2048BoardViewConfig;
  spriteConfig: IGame2048SpriteConfig;
  game2048Config: Game2048Config;
  undoHistoryDepth: number;
  saveData: ISaveData;
  /** Вызывается только для save — происходит нечасто: после ходов, undo и reset. */
  onSave?: (state: ISaveData) => Promise<SaveResult>;
  /** Перезапуск через рестарт сцены. */
  onRestartClick: () => void;
  events: TypedEventsEmitter<IGame2048Events>;
}

interface IRunMoveAnimationStepProps {
  result: IGame2048MoveResult;
  newTile?: Game2048TileModel;
  isVictory: boolean;
  onComplete: () => void;
}

interface ISpawnMoveEffectsProps {
  result: IGame2048MoveResult;
  newTile?: Game2048TileModel;
  isVictory: boolean;
}

/** Управляет моделью, полем, вводом и публичным состоянием игры 2048. */
export class Game2048 {
  private grid: Game2048GridModel;
  private boardView: Game2048BoardView;
  private inputController: Game2048InputController;

  private get gameEvents() {
    return this.props.events;
  }

  private gameState: State<IGame2048State>;

  /** Создает игровой компонент в указанной сцене. */
  constructor(private props: IGame2048Props) {
    const { scene, boardConfig, spriteConfig, saveData } = props;
    const initialBoardSnapshot = saveData.boardSnapshot;
    let isSnapshotRestored = false;

    this.grid = this.createGridModel();
    if (initialBoardSnapshot) {
      isSnapshotRestored = this.restoreInitialSnapshot(initialBoardSnapshot);
    }

    const initialState = createInitState({
      grid: this.grid,
      saveData,
      undoHistoryDepth: props.undoHistoryDepth,
      game2048Config: props.game2048Config,
    });

    this.gameState = new State<IGame2048State>(initialState);

    this.boardView = new Game2048BoardView({ scene, spriteConfig, boardConfig });
    this.boardView.render(this.grid, !isSnapshotRestored);
    this.inputController = new Game2048InputController({
      scene,
      boardView: this.boardView,
      onMove: this.handleMove.bind(this),
    });

    this.onStateDerivedUpdate(initialState);
    this.subscribeToSceneEvents();
    this.subscribeToHammerInput();
    this.emitMaxTile();
  }

  /** Уничтожает все компоненты игрового вида. */
  destroy(): void {
    this.inputController.destroy();
    this.unsubscribeFromHammerInput();
    this.gameState.unSubScribeAll();
    this.boardView.destroy();
  }

  /** Возвращает наблюдаемое состояние для UI и менеджеров сцены. */
  getState(): Observable<IGame2048State> {
    return this.gameState;
  }

  /**
   * Сбрасывает игру к начальному состоянию.
   * имущество сохраняем
   * */
  reset(): void {
    const currentState = this.gameState.getState();
    const newGameData = {
      ...getEmptySaveState(),
      bestScore: currentState.bestScore,
      hammerAmount: currentState.hammerAmount,
      undoAmount: currentState.undoAmount,
    };
    this.saveGameData(newGameData);
    this.props.onRestartClick();
  }

  /** Излучает готовое состояние завершенной партии для внешнего представления. */
  emitEndState(): void {
    const state = this.gameState.getState();
    if (state.playWinState === "playing") return;
    const { game2048Config } = this.props;
    this.gameEvents.emit("game2048EndStateReady", {
      playWinState: state.playWinState,
      undoAmount: state.undoAmount,
      historyLength: state.history.length,
      canContinueAfterWin: state.canContinueAfterWin,
      isMaxTileReached: state.isMaxTileReached,
      winValue: game2048Config.winValue,
      maxTileValue: game2048Config.maxTileValue,
    });
  }

  /** Выполняет ход игрока. */
  private handleMove(direction: MoveDirection): void {
    const prevState = this.gameState.getState();
    if (prevState.toolMode === "hammer" || this.isMoveBlocked()) {
      return;
    }

    const snapshotBeforeAction = this.grid.createHistorySnapshot();
    const result = this.grid.move(direction);
    if (!result.moved) {
      return;
    }

    const newTile = this.grid.addRandomTile("move");
    const nextState = createMoveState({
      prevState,
      grid: this.grid,
      snapshotBeforeAction,
      undoHistoryDepth: this.props.undoHistoryDepth,
      mergeEvents: result.mergeEvents,
      game2048Config: this.props.game2048Config,
    });

    this.onStateDerivedUpdate(nextState);
    this.gameState.setState(nextState);

    if (nextState.maxReachedTile > prevState.maxReachedTile) {
      this.emitMaxTile();
    }
    this.saveGameData();

    this.runMoveAnimationStep({
      result,
      newTile,
      isVictory: nextState.playWinState === "win",
      onComplete: () => this.completeMoveAfterAnimation(),
    });
  }

  /** Запускает все визуальные фазы успешного хода и завершает шаг через callback. */
  private runMoveAnimationStep({ newTile, result, isVictory, onComplete }: IRunMoveAnimationStepProps): void {
    const { boardView, gameEvents } = this;

    gameEvents.emit("tilesMove");
    boardView.playMove({
      grid: this.grid,
      result,
      newTile,
      onSlideComplete: () => this.spawnMoveEffects({ result, newTile, isVictory }),
      onComplete,
    });
  }

  /** Завершает ход после полного animation-step и излучает итоговое состояние партии. */
  private completeMoveAfterAnimation(): void {
    const { game2048Config } = this.props;
    const settledState = createInputUnlockedState({
      prevState: this.gameState.getState(),
      grid: this.grid,
      game2048Config: game2048Config,
    });

    this.gameState.setState(settledState);

    this.emitEndState();
  }

  /** Запускает частицы, которые должны появиться после slide-фазы хода. */
  private spawnMoveEffects(props: ISpawnMoveEffectsProps): void {
    const { newTile, result } = props;
    this.spawnMergeEffects(result.mergeEvents);

    if (newTile) {
      const center = this.boardView.getCellCenter(newTile.row, newTile.col);
      this.gameEvents.emit(
        "game2048NewTileParticles",
        this.createEffectPayload(center, newTile.value),
      );
    }

    if (props.isVictory) {
      this.spawnVictoryEffects();
    }
  }

  /** Проверяет, заблокирован ли сейчас ввод ходов. */
  private isMoveBlocked(): boolean {
    const s = this.gameState.getState();
    return s.playWinState !== "playing" || s.inputLocked;
  }

  /** Подписывает игру на команды UI и диалогов сцены. */
  private subscribeToSceneEvents(): void {
    this.gameEvents.on("game2048NewGameRequest", () => this.reset());
    this.gameEvents.on("game2048UndoRequest", () => this.undo());
    this.gameEvents.on("game2048RewardGranted", ({ rewardType }) => this.applyReward(rewardType));
    this.gameEvents.on("game2048ContinueRequest", () => this.continueAfterWin());
    this.gameEvents.on("game2048HammerButtonRequest", () => this.onHammerRequest());
    this.gameEvents.on("hammerDisableRequest", () => this.disableHammer());
  }

  /** Подписывает hammer-режим на глобальный pointer-ввод сцены. */
  private subscribeToHammerInput(): void {
    const { scene } = this.props;
    scene.input.on(Phaser.Input.Events.POINTER_MOVE, this.handleHammerPointerMove, this);
    scene.input.on(Phaser.Input.Events.POINTER_DOWN, this.handleHammerPointerDown, this);
  }

  /** Снимает pointer-подписки hammer-режима. */
  private unsubscribeFromHammerInput(): void {
    const { scene } = this.props;
    scene.input.off(Phaser.Input.Events.POINTER_MOVE, this.handleHammerPointerMove, this);
    scene.input.off(Phaser.Input.Events.POINTER_DOWN, this.handleHammerPointerDown, this);
  }

  /** Обрабатывает запрос UI на включение молотка через state. */
  private onHammerRequest(): void {
    const prevState = this.gameState.getState();
    const { game2048Config } = this.props;
    if (
      prevState.hammerAmount < 1 ||
      prevState.filledTiles < game2048Config.hammerBoardFillAmountMin
    ) {
      return;
    }
    if (this.isMoveBlocked()) {
      return;
    }

    const nextState = createToolModeState({
      prevState: this.gameState.getState(),
      toolMode: "hammer",
    });

    this.onStateDerivedUpdate(nextState);
    this.gameState.setState(nextState);
  }

  /** Применяет внешние эффекты выбранного в state инструмента. */
  private activateToolMode(toolMode: Game2048ToolMode): void {
    switch (toolMode) {
      case "hammer": {
        this.inputController.setSwipesEnabled(false);
        this.updateHammerHover(this.props.scene.input.activePointer);
        break;
      }
      case "wand": {
        this.inputController.setSwipesEnabled(true);
        this.boardView.setHammerTile(undefined);
        break;
      }
    }
    this.gameEvents.emit("setCursor", { type: toolMode });
  }

  /** Обновляет плитку под курсором молотка. */
  private handleHammerPointerMove(pointer: Phaser.Input.Pointer): void {
    if (this.gameState.getState().toolMode !== "hammer") {
      return;
    }
    this.updateHammerHover(pointer);
  }

  /** Удаляет плитку по клику молотком и завершает режим инструмента. */
  private handleHammerPointerDown(pointer: Phaser.Input.Pointer): void {
    if (this.gameState.getState().toolMode !== "hammer" || this.isMoveBlocked()) {
      return;
    }

    if (!this.boardView.containsPoint(pointer.worldX, pointer.worldY)) {
      return;
    }

    const hit = this.boardView.findTileHitAtPoint({
      grid: this.grid,
      x: pointer.worldX,
      y: pointer.worldY,
    });

    if (!hit) {
      this.disableHammer();
      return;
    }

    this.handleHammerTileClick(hit.row, hit.col);
  }

  /** Выключает активный hammer-режим без расходования молотка. */
  private disableHammer(): void {
    const prevState = this.gameState.getState();
    if (prevState.toolMode !== "hammer") {
      return;
    }

    const nextState = createToolModeState({
      prevState,
      toolMode: "wand",
    });

    this.onStateDerivedUpdate(nextState);
    this.gameState.setState(nextState);
  }

  /** Ставит дрожание на плитку под молотком или снимает его вне плиток. */
  private updateHammerHover(pointer: Phaser.Input.Pointer): void {
    const hit = this.boardView.findTileHitAtPoint({
      grid: this.grid,
      x: pointer.worldX,
      y: pointer.worldY,
    });
    this.boardView.setHammerTile(hit?.id);
  }

  /** Применяет удаление плитки как ход с undo-снимком и сохранением партии. */
  private handleHammerTileClick(row: number, col: number): void {
    const tile = this.grid.getTile(row, col);
    if (!tile) {
      return;
    }

    const effectPayload = this.createEffectPayload(
      this.boardView.getCellCenter(row, col),
      tile.value,
    );
    /** Молоток считается успешным ходом, поэтому undo должен вернуться к доске до удаления плитки. */
    const snapshotBeforeAction = this.grid.createHistorySnapshot();

    if (!this.grid.removeTile(row, col)) {
      return;
    }

    this.gameEvents.emit("game2048Hammer", effectPayload);

    const prevState = this.gameState.getState();
    const nextState = createHammerState({
      prevState,
      grid: this.grid,
      snapshotBeforeAction,
      undoHistoryDepth: this.props.undoHistoryDepth,
      game2048Config: this.props.game2048Config,
    });

    this.onStateDerivedUpdate(nextState);
    this.gameState.setState(nextState);

    this.boardView.render(this.grid);
    this.saveGameData();
  }

  /** Отменяет последний успешный ход. */
  private undo(): void {
    const prevState = this.gameState.getState();
    if (prevState.history.length < 1 || prevState.undoAmount < 1) {
      return;
    }

    const { history } = prevState;
    const snapshot = history[history.length - 1];
    if (!snapshot) {
      return;
    }

    this.grid.restoreHistorySnapshot(snapshot);

    const nextState = createUndoState({
      prevState,
      grid: this.grid,
      game2048Config: this.props.game2048Config,
    });

    this.onStateDerivedUpdate(nextState);
    this.gameState.setState(nextState);

    this.boardView.render(this.grid);
    this.gameEvents.emit("game2048ClearParticles");
    this.saveGameData();
  }

  private undoForReward() {
    const { undoRewardAmount } = this.props.game2048Config;
    this.gameState.setState((prev) => ({
      ...prev,
      undoAmount: prev.undoAmount + undoRewardAmount,
    }));

    /** применяем сразу отмену - и она уже обновит состояние **/
    this.undo();
  }

  private hammerForReward() {
    const { hammerRewardAmount } = this.props.game2048Config;
    this.gameState.setState((prev) => ({
      ...prev,
      hammerAmount: prev.hammerAmount + hammerRewardAmount,
    }));
    this.saveGameData();
  }

  /** Применяет подтвержденную внешним окружением награду. */
  private applyReward(rewardType: "undo" | "hammer"): void {
    switch (rewardType) {
      case "undo":
        this.undoForReward();
        break;
      case "hammer":
        this.hammerForReward();
        break;
    }
  }

  /** Продолжает игру после победного диалога. */
  private continueAfterWin(): void {
    if (!this.gameState.getState().canContinueAfterWin) {
      return;
    }

    const nextState = createContinueState({
      prevState: this.gameState.getState(),
      grid: this.grid,
      game2048Config: this.props.game2048Config,
    });

    this.onStateDerivedUpdate(nextState);
    this.gameState.setState(nextState);
  }

  /** Создает частицы для всех слияний текущего хода через события сцены. */
  private spawnMergeEffects(mergeEvents: IGame2048MergeEvent[]): void {
    for (const event of mergeEvents) {
      const center = this.boardView.getCellCenter(event.row, event.col);
      this.gameEvents.emit(
        "game2048MergeParticles",
        this.createEffectPayload(center, event.value),
      );
    }
  }

  /** Создает праздничный эффект при достижении плитки 2048. */
  private spawnVictoryEffects(): void {
    const center = this.boardView.getBoardCenter();
    this.gameEvents.emit(
      "game2048VictoryParticles",
      this.createEffectPayload(center, this.props.game2048Config.winValue),
    );
  }

  /** Создает модель поля с правилами текущего уровня. */
  private createGridModel(): Game2048GridModel {
    const { game2048Config } = this.props;
    return new Game2048GridModel({
      size: game2048CoreConfig.gridSize,
      tileMergePolicy: createTileMergePolicy({ maxTileValue: game2048Config.maxTileValue }),
      tileSpawnPolicy: createTileSpawnPolicy({ game2048Config }),
    });
  }

  /** Восстанавливает стартовый снимок доски после runtime-валидации сохранения. */
  private restoreInitialSnapshot(snapshot: unknown): boolean {
    if (!isValidHistorySnapshot(snapshot)) {
      console.warn("Invalid 2048 board snapshot");
      return false;
    }
    this.grid.restoreHistorySnapshot(snapshot);
    /** Экран победы не восстанавливается из сейва: старая победная плитка считается уже увиденной. */
    if (this.grid.getMaxValue() >= this.props.game2048Config.winValue) {
      this.grid.won = true;
    }

    return true;
  }

  /** Создает нейтральный payload игрового эффекта без оформления конкретного рескина. */
  private createEffectPayload(
    position: { x: number; y: number },
    value: number,
  ): IGame2048EffectPayload {
    return {
      x: position.x,
      y: position.y,
      value,
    };
  }

  /** Излучает компактное событие прогресса, чтобы фон не зависел от Observable состояния игры. */
  private emitMaxTile(): void {
    this.gameEvents.emit("game2048MaxTileChange", {
      maxTile: this.gameState.getState().maxReachedTile,
    });
  }

  /**
   * Заказывает сохранение
   * по умолчанию - текущее состояние
   *  */
  private saveGameData(saveData?: ISaveData): void {
    saveData = saveData ?? mapGame2SaveData(this.gameState.getState());
    this.props.onSave?.(saveData);
  }

  /**
   * Применяет временные изменения модели, которые пока выводятся из полей state.
   *
   * TODO: рассмотреть модель тщательнее — `grid.won` смешивает доску, диалог победы и save/undo.
   */
  private onStateDerivedUpdate(state: IGame2048State): void {
    if (state.playWinState === "win") {
      this.grid.won = true;
    }

    /** Применяет внешние эффекты инструмента после изменения state. */
    this.activateToolMode(state.toolMode);
  }
}
