/**
 *  храним кэши данных в строках
 *  - проверяем что новые данные совпадают
 *  - заносим в кэш
 ***/
export class SaveCacheStrategy {
  private jsonMap: Record<string, string|undefined> = {};

  isAlreadySaved(key: string, value: unknown): boolean {
    return this.jsonMap[key] === this.getString({ key, value });
  }

  markSaved(key: string, value: unknown) {
    this.jsonMap[key] = this.getString({ key, value });
  }

  private getString({ key, value }: { key: string; value: unknown }): string | undefined {
    try {
      return JSON.stringify({ key, value });
    } catch (e) {
      console.warn(e);
    }
  }
}
