import type { IHistoryTile } from "./types";

let nextTileId = 1;

interface IGame2048TileModelProps {
  value: number;
  row: number;
  col: number;
}

interface IFromHistoryDataProps {
  data: IHistoryTile;
  row: number;
  col: number;
}

/** Описывает значение и положение одной плитки на поле. */
export class Game2048TileModel {
  id: number;
  value: number;
  row: number;
  col: number;

  /** Создает плитку с указанным значением и позицией. */
  constructor(props: IGame2048TileModelProps) {
    this.id = nextTileId;
    nextTileId += 1;

    this.value = props.value;
    this.row = props.row;
    this.col = props.col;
  }

  /** Создает runtime-плитку из чистых данных истории. */
  static fromHistoryData(props: IFromHistoryDataProps): Game2048TileModel {
    const { data, row, col } = props;
    const tile = new Game2048TileModel({ value: data.value, row, col });

    tile.id = data.id;

    if (tile.id >= nextTileId) {
      nextTileId = tile.id + 1;
    }

    return tile;
  }

  /** Сериализует плитку в чистые данные истории без runtime-анимаций. */
  toHistoryData(): IHistoryTile {
    return {
      id: this.id,
      value: this.value,
    };
  }

  /** Перемещает плитку в новую клетку. */
  setPosition(row: number, col: number): void {
    this.row = row;
    this.col = col;
  }
}
