import {
  CindDialogManager,
  Cinderella2048BackgroundManager,
  Cinderella2048EffectsLayer,
  Cinderella2048Ui,
  FireworksLayer
} from "./components";
import { getConfig } from "../../getConfig";
import { sceneKeyConfig } from "../sceneKeyConfig";
import { CursorManager, HammerInfoCard } from "../shared";
import { listenSoundEvents, musicConfig } from "../../config.sound";
import { adService, gameEventBus } from "../../services";
import { AdsOverlayManager, type Game2048, SoundPlayerFeature } from "../../common";
import { createCinderella2048Game } from "./createCinderella2048Game";

/** Phaser-сцена игрового компонента Cinderella 2048. */
export class Cinderella2048Scene extends Phaser.Scene {
  private gameComponent?: Game2048;

  /**
   * Создает сцену Cinderella 2048.
   * */
  constructor() {
    super(sceneKeyConfig.game);
  }

  /** Создает игровой компонент и подписку на shutdown. */
  create(): void {
    const scene = this;
    const events = gameEventBus;
    listenSoundEvents(scene);

    /**
     *  В игре пока нет настроек звука и музыки
     *  поэтому ставим заглушку
     *  главная фича - просто ловить эвенты звука с scene events
     *  и применять их
     **/
    new SoundPlayerFeature({
      scene,
      musicConfig,
      events,
      getSettings: () => ({
        isMusicOn: false,
        isSoundOn: true,
      }),
    });

    const { backgroundConfig, boardConfig, game2048Config } = getConfig();
    const backgroundManager = new Cinderella2048BackgroundManager({
      scene,
      events,
      backgroundStages: backgroundConfig.stages,
    });
    const gameComponent = createCinderella2048Game({
      scene,
      boardConfig,
      game2048Config,
    });

    this.gameComponent = gameComponent;

    const ui = new Cinderella2048Ui({
      scene,
      events,
      game2048Config,
      gameState: gameComponent.getState(),
      isHammerFeatureEnabled: game2048Config.hammerFeature,
      isUndoFeatureEnabled: game2048Config.undoFeature,
    });
    const hammerInfoCard = game2048Config.hammerFeature
      ? new HammerInfoCard({
          scene,
          events,
          onRemoveClick: () => events.emit("hammerDisableRequest"),
        })
      : undefined;
    /**
     * Частицы плиток и салют являются независимыми потребителями общих событий scene:
     * каждый слой владеет своими emitters и не вызывает другой слой напрямую.
     **/
    const effectsLayer = new Cinderella2048EffectsLayer({ scene, events });
    const fireworksLayer = new FireworksLayer({ scene, events });
    const adOverlayManager = new AdsOverlayManager({
      scene,
      adService: adService,
      events,
    });
    const gameOverDialogManager = new CindDialogManager({
      scene,
      events,
    });
    const cursorManager = new CursorManager({
      scene,
      events,
      defaultType: game2048Config.cursorDefault,
    });

    this.events.once(Phaser.Scenes.Events.SHUTDOWN, () => {
      gameEventBus.unSubscribeAll(); // обязательная отписка
      backgroundManager.destroy();
      gameComponent.destroy();
      ui.destroy();
      hammerInfoCard?.destroy();
      effectsLayer.destroy();
      fireworksLayer.destroy();
      adOverlayManager.destroy();
      gameOverDialogManager.destroy();
      cursorManager.destroy();
      this.gameComponent = undefined;
    });

    /** Оповещаем о начале игры - вдруг надо показать UI **/
    gameComponent.emitEndState();
  }
}
